@Slf4j
@PluginDescriptor(
	name = "Time Served",
	description = "Tools for the Time Served clan: auto-submits bingo tile proofs when you get a matching drop,"
		+ " plus \"!rank\"/\"!verify\" chat commands to check a clan member's rank eligibility and gear requirements.",
	tags = {"bingo", "clan", "loot", "screenshot", "verify", "rank", "twitch"}
)
public class BingoPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BingoConfig config;

	@Inject
	private BingoApiClient api;

	@Inject
	private DrawManager drawManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BingoCodewordOverlay codewordOverlay;

	@Inject
	private ChatCommandManager chatCommandManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private BingoPanel bingoPanel;

	@Inject
	private PendingSubmissionStore pendingStore;

	private NavigationButton bingoNavButton;

	/**
	 * Runs the site's "Auto-Verify" rank check for the given name - what
	 * this plugin's "!verify" command used to be before it was split in
	 * two (see VERIFY_COMMAND below): "!rank" now reports which rank tier
	 * someone is eligible for, while "!verify" checks the separate,
	 * harder clan-gear requirement. "!rank <name>" really is sent as a
	 * normal chat message, same as "!lvl" or "!kc" - visible to everyone
	 * nearby, plugin or not. The looked-up result then overwrites that
	 * message's displayed text (see setChatReply below), the exact
	 * technique RuneLite's own bundled chat commands use, which only ever
	 * affects local rendering: it shows up for other viewers whose own
	 * client also has this command registered (i.e. other Time Served
	 * Bingo plugin users), while anyone else just sees the plain,
	 * unmodified "!rank <name>" they actually typed.
	 */
	private static final String RANK_COMMAND = "!rank";

	/**
	 * Checks whether a member meets the clan's hard gear/kc requirement -
	 * the same three-way check ("Auto-Verify" used to just mean rank
	 * eligibility; this is a separate, stricter gate) the site itself runs
	 * on its Clan Rankings page: 6+ Crystal Armour Seeds plus an Enhanced
	 * Crystal Weapon Seed, OR 800+ Corrupted Gauntlet kc, OR a Twisted
	 * Bow. Same visible-reply mechanism as !rank - see setChatReply.
	 */
	private static final String VERIFY_COMMAND = "!verify";

	/** Same visible-reply mechanism as !rank - see setChatReply. */
	private static final String NEEDED_COMMAND = "!needed";

	/** Same visible-reply mechanism as !rank - see setChatReply. */
	private static final String LIVE_COMMAND = "!live";

	/** Same visible-reply mechanism as !rank - see setChatReply. */
	private static final String EVENT_COMMAND = "!event";

	/** Guards registerCommands()/unregisterCommands() so either is safe to call more than once in a row. */
	private boolean commandsRegistered;

	/** Sync-reminder fires at most once per plugin session, on whichever outcome comes back first. */
	private boolean checkedRuneProfileSync;

	/**
	 * Whether the site last reported an active bingo event, from the combined
	 * poll (see BingoApiClient#fetchPluginPoll). The expensive board fetch
	 * only ever runs while this is true, so between events the plugin's bingo
	 * half costs nothing at all while its clan half (chat commands,
	 * live-stream and broadcast notifications) keeps working normally.
	 * Defaults true so the plugin behaves normally until it has actually
	 * heard otherwise, rather than starting paused on a fresh session.
	 */
	private volatile boolean bingoActive = true;

	/**
	 * Item id -> the tiles it can satisfy, for this player's own team only.
	 * Replaced wholesale on refresh; read from the client thread on every loot
	 * event, so it's a concurrent map rather than a plain one.
	 */
	private final Map<Integer, List<BoardResponse.Tile>> tilesByItemId = new ConcurrentHashMap<>();

	/** Ground items currently visible whose id satisfies an outstanding tile. */
	private final Map<TileItem, TrackedGroundItem> trackedGroundItems = new ConcurrentHashMap<>();

	/**
	 * Item ids handleLoot() just confirmed came from a real loot event - an
	 * NPC kill, a chest, a casket, anything RuneLite's own NpcLootReceived/
	 * LootReceived fired for - each holding a countdown of how many more game
	 * ticks it still counts for. onItemSpawned checks this before beaming an
	 * item: the ground spawn from an actual drop lands on the same tick as the
	 * loot event in practice, but manually dropping the exact same item from
	 * your own inventory fires the identical ItemSpawned event with nothing
	 * here to match it against, so it's correctly left unbeamed. A couple of
	 * ticks of grace rather than same-tick-only, since RuneLite doesn't
	 * guarantee event ordering within a tick.
	 */
	private final Map<Integer, Integer> recentlyLootedItemTicks = new ConcurrentHashMap<>();
	private static final int LOOT_GRACE_TICKS = 2;

	/**
	 * A ground item spawn matching a tile's watch list, seen before its own
	 * loot event confirmation reached recentlyLootedItemTicks. Confirmed live
	 * (a goblin's hammer submitted fine but never got a beam): RuneLite does
	 * not guarantee ItemSpawned fires after NpcLootReceived/LootReceived for
	 * the same drop, only that they land close together, so "not confirmed
	 * yet" at spawn time is not the same as "never will be" - this holds the
	 * spawn briefly instead of discarding it, and handleLoot() reaches back
	 * into this map to beam it retroactively the moment confirmation arrives.
	 */
	private final Map<TileItem, PendingSpawn> pendingUnconfirmedSpawns = new ConcurrentHashMap<>();

	private static class PendingSpawn
	{
		final ItemSpawned event;
		final int ticksRemaining;

		PendingSpawn(ItemSpawned event, int ticksRemaining)
		{
			this.event = event;
			this.ticksRemaining = ticksRemaining;
		}
	}

	/** A tracked ground item's real 3D loot beam - the beam is the whole
	 * highlight now, RuneLite's own Ground Items plugin already labels the
	 * item itself, so this doesn't also draw a tile-name overlay on top. */
	static class TrackedGroundItem
	{
		final BingoLootbeam beam;

		TrackedGroundItem(BingoLootbeam beam)
		{
			this.beam = beam;
		}
	}

	/**
	 * Drop proofs that failed to send over the network, waiting to retry.
	 * Backed by PendingSubmissionStore, which mirrors every entry to disk -
	 * startUp() reloads whatever survived a previous session, so a client
	 * restart mid-outage no longer silently loses a real drop with no way
	 * to reconstruct it afterwards.
	 */
	private final Deque<PendingSubmissionStore.PendingItem> retryQueue = new ConcurrentLinkedDeque<>();

	/**
	 * Caps how many failed items this plugin holds in memory (and thus on
	 * disk) at once. Generous rather than tight, now that a restart can't
	 * wipe the queue - this just bounds a genuinely prolonged, unresolved
	 * outage rather than protecting against a restart the way it used to.
	 */
	private static final int MAX_RETRY_QUEUE = 100;

	/**
	 * Tile id -> when it was last attempted (submitted or refused). This exists
	 * purely to collapse the near-simultaneous duplicate: RuneLite's loot
	 * tracker republishes most NPC kills as both NpcLootReceived and
	 * LootReceived, so a single kill would otherwise be submitted twice.
	 *
	 * <p>Deliberately NOT a "don't retry this tile" flag with any longer
	 * lifetime than that: if a submission gets rejected by an admin, a later
	 * genuine re-drop of the same item must be able to try again. The server
	 * is the actual authority on whether a tile still needs proof (it checks
	 * approved+pending counts fresh on every request), so this cache only
	 * needs to survive long enough to de-duplicate one kill's events, not
	 * until the next board refresh.
	 */
	private final Map<String, Long> recentAttempts = new ConcurrentHashMap<>();
	// 2 game ticks (a tick is 600ms) - comfortably longer than the gap between
	// NpcLootReceived and LootReceived firing for the SAME kill (they land in
	// the same tick, or very close), but short enough that genuinely separate
	// kills seconds apart are never mistaken for duplicates. This used to be
	// 30 seconds, which was a real bug: rapid-killing a fast-dying, fast-
	// respawning monster (e.g. farming bones from something weak) meant only
	// the FIRST kill in any 30-second span ever got submitted - every other
	// real, separate kill in that window was silently dropped, since this
	// cache is keyed on tile id alone with no idea whether a later hit is a
	// genuine new kill or the same kill's duplicate event.
	private static final long DEDUPE_WINDOW_MILLIS = 1200L;

	private boolean recentlyAttempted(String tileId)
	{
		long now = System.currentTimeMillis();
		Long last = recentAttempts.putIfAbsent(tileId, now);
		if (last == null)
		{
			return false;
		}
		if (now - last > DEDUPE_WINDOW_MILLIS)
		{
			// Stale - treat as a fresh attempt and reset the window.
			recentAttempts.put(tileId, now);
			return false;
		}
		return true;
	}

	@Provides
	BingoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BingoConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(codewordOverlay);
		if (config.enableClanCommands())
		{
			registerCommands();
		}

		// Re-resolve the panel's UI delegates against whatever look-and-feel is
		// actually installed now.
		//
		// BingoPanel is an @Inject field, so it is constructed when this plugin
		// object is - which can land before the client has swapped in its own
		// look-and-feel. Anything built in that window keeps the UI delegate it
		// was given at construction (Swing's default Metal), and nothing calls
		// updateUI() on it afterwards, so it renders with Metal's thick
		// arrow-button scrollbar while every other panel in the sidebar has the
		// client's thin flat one. Reported from a real client as the bingo
		// board having "a weird, really thick, blue, window type scroll bar".
		//
		// Doing it here rather than in the constructor is the whole point:
		// startUp() runs well after the client's UI is up. It is a no-op when
		// the panel was already built under the right look-and-feel, and it
		// only re-reads UI defaults - explicitly set colours, fonts and borders
		// are component properties and survive it.
		SwingUtilities.invokeLater(() -> SwingUtilities.updateComponentTreeUI(bingoPanel));

		bingoNavButton = NavigationButton.builder()
			.tooltip("Bingo")
			.icon(buildNavIcon())
			.priority(5)
			.panel(bingoPanel)
			.build();
		// Not added here unconditionally - see updateNavVisibility(). Team
		// membership isn't known yet at this point (refreshMyTeam() below is
		// asynchronous), so the icon only appears once that resolves.

		List<PendingSubmissionStore.PendingItem> restored = pendingStore.loadAll();
		if (!restored.isEmpty())
		{
			log.debug("Restored {} pending submission(s) from a previous session", restored.size());
		}
		for (PendingSubmissionStore.PendingItem item : restored)
		{
			enqueueRetry(item);
		}

		// Fills the sidebar panel straight away rather than leaving it empty
		// until the first tick. Everything after this goes through poll().
		refreshMyTeam();
		refreshBoardNow();
	}

	/**
	 * A plain drawn icon rather than a bundled PNG resource: three small squares on the sidebar rail,
	 * echoing a bingo tile without needing an image asset shipped alongside the plugin.
	 */
	private static BufferedImage buildNavIcon()
	{
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = icon.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(220, 138, 0));
		int cell = 4;
		int gap = 2;
		for (int row = 0; row < 3; row++)
		{
			for (int col = 0; col < 3; col++)
			{
				if (row == 1 && col == 1)
				{
					continue;
				}
				g.fillRect(1 + col * (cell + gap), 1 + row * (cell + gap), cell, cell);
			}
		}
		g.dispose();
		return icon;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(codewordOverlay);
		unregisterCommands();
		clientToolbar.removeNavigation(bingoNavButton);
		bingoPanel.dispose();
		tilesByItemId.clear();
		for (TrackedGroundItem tracked : trackedGroundItems.values())
		{
			tracked.beam.remove();
		}
		trackedGroundItems.clear();
		recentlyLootedItemTicks.clear();
		pendingUnconfirmedSpawns.clear();
		recentAttempts.clear();
		retryQueue.clear();
		checkedRuneProfileSync = false;
		bingoActive = true;
		lastBoardStamp = null;
		lastBoardVersion = null;
		lastPolledVersion = null;
		nextPollAllowedAt = 0L;
		lastPollAt = 0L;
		consecutivePollFailures = 0;
		pollIntervalMillis = POLL_INTERVAL_DEFAULT_MILLIS;
		lastBoardFetchAt = 0L;
		myTeamId = null;
		panelWasVisible = false;
		lastBoard = null;
	}

	/** Idempotent - safe to call when the commands are already registered (guarded by commandsRegistered). */
	private void registerCommands()
	{
		if (commandsRegistered)
		{
			return;
		}
		chatCommandManager.registerCommandAsync(RANK_COMMAND, this::onRankCommand);
		chatCommandManager.registerCommandAsync(VERIFY_COMMAND, this::onVerifyCommand);
		chatCommandManager.registerCommandAsync(NEEDED_COMMAND, this::onNeededCommand);
		chatCommandManager.registerCommandAsync(LIVE_COMMAND, this::onLiveCommand);
		chatCommandManager.registerCommandAsync(EVENT_COMMAND, this::onEventCommand);
		commandsRegistered = true;
	}

	/** Idempotent - safe to call when the commands aren't currently registered. */
	private void unregisterCommands()
	{
		if (!commandsRegistered)
		{
			return;
		}
		chatCommandManager.unregisterCommand(RANK_COMMAND);
		chatCommandManager.unregisterCommand(VERIFY_COMMAND);
		chatCommandManager.unregisterCommand(NEEDED_COMMAND);
		chatCommandManager.unregisterCommand(LIVE_COMMAND);
		chatCommandManager.unregisterCommand(EVENT_COMMAND);
		commandsRegistered = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// Fires on every area/instance load, not just a literal login -
			// during something like raids this can happen many times in quick
			// succession. So this asks for a poll rather than a board fetch:
			// poll() rate-limits itself and only fetches the board if it has
			// actually changed, which makes a burst of instance loads cost
			// nothing while still getting a real logging-in player caught up
			// immediately instead of up to a minute later.
			poll();
			checkRuneProfileSync();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BingoConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("apiKey".equals(event.getKey()))
		{
			// A new key can mean a different member, and so a different
			// team - re-resolve both rather than wait for a tick.
			refreshMyTeam();
			refreshBoardNow();
		}
		else if ("showSidebar".equals(event.getKey()))
		{
			updateNavVisibility();
		}
		else if ("enableClanCommands".equals(event.getKey()))
		{
			if (config.enableClanCommands())
			{
				registerCommands();
			}
			else
			{
				unregisterCommands();
			}
		}
		else if ("highlightGroundItems".equals(event.getKey()))
		{
			if (!config.highlightGroundItems())
			{
				// onItemSpawned already refuses to create a *new* beam once
				// this is off - but that leaves whatever beams already
				// existed the moment the toggle flipped untouched, since
				// nothing else ever removed them except the ground item
				// itself despawning. Without this, the only way to clear one
				// was to pick the item up and drop it again.
				for (TrackedGroundItem tracked : trackedGroundItems.values())
				{
					tracked.beam.remove();
				}
				trackedGroundItems.clear();
				// Also drop anything still waiting on loot confirmation -
				// without this, a spawn seen a tick before the toggle flipped
				// off could still get beamed right after, via
				// confirmPendingSpawns.
				pendingUnconfirmedSpawns.clear();
			}
			else
			{
				// Symmetric case: something may have dropped and be sitting
				// on the ground right now, untouched, from while this was
				// off - beaming is otherwise purely reactive to a fresh
				// spawn event, so without this it would go unbeamed until
				// some unrelated later drop happened to trigger one.
				rescanGroundItemsForBeams();
			}
		}
	}

	/**
	 * The plugin's whole periodic workload: one request, once a minute, only
	 * while actually logged in, and only for members who have a plugin key
	 * set at all (see hasAnythingToPollFor).
	 *
	 * <p>This used to be three requests every minute - bingo status, clan
	 * broadcast, live streams - fired unconditionally for as long as the
	 * client was open, logged in or not, for every install regardless of
	 * whether they had anything to do with bingo. That is roughly 4,300
	 * requests per member per day doing nothing, and across the clan it was
	 * enough to exhaust the site's hosting quotas outright, at which point
	 * the site started failing for everyone. Broadcast and live-stream
	 * notifications were removed entirely rather than just merged, so the
	 * only thing left to poll for is bingo state, and only bingo participants
	 * have any reason to ask for it - between events, or for the several
	 * hundred members who just use the chat commands, this tick makes zero
	 * requests at all.
	 *
	 * <p>Broadcast was briefly reintroduced over Vercel Blob (2026-09-07) on
	 * the reasoning that reading a static file costs no function invocations
	 * and never touches the database - both true - and removed again the same
	 * day once it turned out every blob URL read still bills an Edge Request
	 * whether it hits cache or not. Nothing about moving the *answer* off the
	 * database changes how many times the *question* is asked, and at 100-500
	 * members that question is the entire cost. Don't reintroduce any
	 * unconditional periodic check here without doing that arithmetic first.
	 *
	 * <p>Nothing runs while logged out either: every result this could
	 * deliver is a game chat message or a board the player is looking at
	 * in-game, so polling at the login screen would spend requests on
	 * nothing.
	 *
	 * <p>The tick itself is deliberately still one minute: the point was
	 * never to make a participant wait longer for a board update, it was to
	 * stop the whole clan paying for answers nobody but a participant ever
	 * needed.
	 */
	@Schedule(period = 1, unit = ChronoUnit.MINUTES, asynchronous = true)
	public void scheduledRefresh()
	{
		poll();
	}

	/*
	 * checkBoardState() used to run here as a second half of this tick: a
	 * participant-only call to GET /api/board?resource=status asking "has the
	 * board changed?". It was removed because it was a duplicate request for
	 * an answer poll() had already fetched on the same tick - onPolled reads
	 * boardChangedAt from the same board_config row and does the same three
	 * things with it (refresh the board, retry pending submissions, clear the
	 * failure backoff).
	 *
	 * Its own comment claimed it "isn't adding any load beyond what a
	 * participant's poll() already costs", and that was simply wrong: a
	 * separate URL is a separate CDN cache entry, so it was a separate origin
	 * invocation and a separate database read every single time. During an
	 * event it doubled the rate at which participants woke Neon's compute, for
	 * information they already had.
	 */

	private volatile boolean panelWasVisible;

	/** The last board fetched, kept so xp/kc progress arriving on a poll can be
	 *  applied to it without paying for another board fetch. */
	private volatile BoardResponse lastBoard;

	/**
	 * Updates the held board's xp/kc tiles from progress carried on the poll,
	 * and repaints - no board fetch involved.
	 *
	 * <p>This is the replacement for the server bumping boardChangedAt every
	 * time a number moved, which made every participant re-download the whole
	 * board every two minutes for the duration of an event. Item tiles are
	 * untouched: those only change when somebody submits something, which does
	 * still move the board marker.
	 */
	private void applyGoalProgress(Map<String, Map<String, Long>> goalProgress)
	{
		BoardResponse board = lastBoard;
		if (board == null || goalProgress == null || goalProgress.isEmpty())
		{
			return;
		}

		boolean changed = false;
		for (BoardResponse.Team team : board.getTeams())
		{
			for (BoardResponse.Tile tile : team.getTiles())
			{
				if (!tile.isXpGoal() && !tile.isKcGoal())
				{
					continue;
				}
				Map<String, Long> byTeam = goalProgress.get(tile.goalKind + ":" + tile.goalKey);
				if (byTeam == null)
				{
					continue;
				}
				Long value = byTeam.get(team.id);
				if (value != null && !value.equals(tile.teamProgress))
				{
					tile.teamProgress = value;
					changed = true;
				}
			}
		}

		if (changed)
		{
			SwingUtilities.invokeLater(() -> bingoPanel.refresh(board));
		}
	}

	/**
	 * Notices the sidebar panel being opened and fetches a board for it.
	 *
	 * <p>Costs nothing on its own - it is a local Swing check, no network -
	 * but it is what makes it safe for shouldRefreshBoard to skip fetching a
	 * board while nobody is looking at one. Without it, opening the panel
	 * would show a stale board until the next scheduled tick came round.
	 */
	@Schedule(period = 5, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void checkPanelOpened()
	{
		boolean visible = bingoPanel.isShowing();
		boolean opened = visible && !panelWasVisible;
		panelWasVisible = visible;
		if (opened && bingoActive && !config.apiKey().trim().isEmpty())
		{
			// Deliberately not a cache-busting fetch: nothing has *changed*,
			// this reader simply doesn't have a copy yet, so the shared cached
			// one is exactly right, and asking for the last polled version
			// gets the copy the site keeps until the board next changes.
			lastBoardVersion = null;
			refreshBoard(lastPolledVersion);
		}
	}

	/**
	 * Poll cadence. The scheduler below ticks every minute, but the actual gap
	 * is whatever the site last asked for (PollResponse#pollSeconds), clamped
	 * to this range - the server knows whether an event is on, and can be
	 * retuned without a plugin release, which a hard-coded constant here could
	 * not be. Defaults to one minute until the site has said otherwise.
	 */
	private static final long POLL_INTERVAL_DEFAULT_MILLIS = 60_000L;
	private static final long POLL_INTERVAL_MIN_MILLIS = 60_000L;
	private static final long POLL_INTERVAL_MAX_MILLIS = 15 * 60_000L;

	/**
	 * The slowest the poll gets while the sidebar panel is closed, whatever the
	 * site asks for. Every poll is a billed Edge Request on the site's hosting
	 * plan whether or not it is a cache hit, and with the panel closed nothing
	 * the poll brings is on screen: auto-submission fires off the loot event,
	 * not the poll, and the item watch list only changes when an admin edits
	 * tiles. Opening the panel fetches a board within seconds (see
	 * checkPanelOpened) and puts the poll back on the site's cadence. Measured
	 * on 2026-09-23: the once-a-minute poll of every online participant was
	 * essentially the whole Edge Request meter, over the free plan's limit.
	 */
	private static final long POLL_INTERVAL_PANEL_CLOSED_MILLIS = 3 * 60_000L;

	private volatile long pollIntervalMillis = POLL_INTERVAL_DEFAULT_MILLIS;

	/**
	 * How long to wait after consecutive failures before trying again:
	 * doubles each time, capped well short of "give up".
	 *
	 * <p>Without this, an outage at the site turns every online plugin into a
	 * client retrying once a minute forever, which is exactly the wrong
	 * response - it is maximum load at the moment the site can least afford
	 * it, and it is how a small problem became a total one. Backing off means
	 * a struggling site gets quieter, not louder, and recovers on its own.
	 */
	private static final long BACKOFF_BASE_MILLIS = 60_000L;
	private static final long BACKOFF_MAX_MILLIS = 15 * 60_000L;

	// All three are read and written from OkHttp's callback threads as well as
	// from the scheduler thread, so none of them can be a plain field.
	private volatile long nextPollAllowedAt;
	private volatile long lastPollAt;
	private volatile int consecutivePollFailures;

	/**
	 * Marker for the board this plugin's tile lookup was last built from.
	 * Null means "unknown" - the next poll fetches the board regardless. See
	 * BingoApiClient.PollResponse#boardChangedAt.
	 */
	private volatile String lastBoardStamp;

	/**
	 * The {@code boardVersion} the held board was fetched as, or null when it
	 * was fetched fresh or without one. See BingoApiClient.PollResponse#boardVersion.
	 */
	private volatile String lastBoardVersion;

	/** The {@code boardVersion} the most recent poll reported. */
	private volatile String lastPolledVersion;

	/** When the board was last successfully fetched - see shouldRefreshBoard. */
	private volatile long lastBoardFetchAt;

	/**
	 * Which team this plugin key belongs to. No longer part of the board
	 * response (that is one cached copy shared by everybody), so it is fetched
	 * separately and kept here. Null until the first fetch succeeds, or when
	 * the member genuinely is not on a team.
	 */
	private volatile String myTeamId;

	/**
	 * How long the plugin will go without re-fetching the board while the
	 * sidebar panel is closed.
	 *
	 * <p>The board changes constantly during a busy event - every submission,
	 * every hiscores reconcile - and each change would otherwise have every
	 * online plugin pull the whole thing again. But nearly all of what changes
	 * that often is display data: standings, teammates submissions, goal
	 * totals. The only part the plugin needs while nobody is looking is the
	 * item-id watch list that auto-submission checks drops against, and that
	 * only changes when an admin edits tiles, which does not happen mid-event.
	 *
	 * <p>So: panel open, refresh on every change and stay live. Panel closed,
	 * refresh at this interval, which keeps the watch list current without
	 * paying for a board nobody is reading.
	 */
	private static final long BACKGROUND_BOARD_REFRESH_MILLIS = 10 * 60_000L;

	/**
	 * Runs a poll unless one ran too recently or a backoff is in effect.
	 *
	 * <p>Callable from anything, including things that fire often: the
	 * interval check below is the only gate, and it is deliberately the same
	 * one for a scheduled tick and for a login. An earlier version gave
	 * login-triggered polls a shorter floor so someone logging in would be
	 * caught up immediately, which was both unnecessary and expensive -
	 * GameState.LOGGED_IN fires on every area and instance load, not just a
	 * real login, so during a raid that shorter floor would have roughly
	 * doubled the request rate for exactly the players generating the most of
	 * it. It was also pointless: a player who has actually been logged out is
	 * one who has not been polling, so their last poll is already older than
	 * the interval and they get their immediate catch-up from this check
	 * anyway. An instance load mid-session gets nothing, which is correct -
	 * they were polled a moment ago.
	 */
	private void poll()
	{
		// Nothing this fetches can reach the player while they're logged out -
		// it all arrives as game chat or an in-game board - so polling at the
		// login screen spends requests on notifications with nowhere to go.
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (!hasAnythingToPollFor())
		{
			return;
		}

		long now = System.currentTimeMillis();
		if (now < nextPollAllowedAt)
		{
			return;
		}
		long interval = isPanelVisible()
			? pollIntervalMillis
			: Math.max(pollIntervalMillis, POLL_INTERVAL_PANEL_CLOSED_MILLIS);
		// A second of slack: the scheduler doesn't fire on exact 60s
		// boundaries, and without this a 60s cadence checked against a 60s
		// interval would skip every other tick and silently run at two
		// minutes.
		if (now - lastPollAt < interval - 1_000L)
		{
			return;
		}
		lastPollAt = now;

		api.fetchPluginPoll(this::onPolled, this::onPollFailed);
	}

	/**
	 * Whether this install has any reason to be talking to the site on a timer.
	 *
	 * <p>Live-stream notifications and admin broadcasts are gone - the periodic
	 * poll now exists purely to deliver bingo state to actual participants. A
	 * plugin key is what a bingo participant has, so it is the only reason left
	 * to poll at all: nobody without one has anything for this tick to tell
	 * them, so between events (or for the several hundred members who just use
	 * the chat commands) this install makes zero background requests. The chat
	 * commands are unaffected either way: they are sent when typed, and never
	 * poll.
	 */
	private boolean hasAnythingToPollFor()
	{
		return !config.apiKey().trim().isEmpty();
	}

	private void onPolled(BingoApiClient.PollResponse result)
	{
		consecutivePollFailures = 0;
		nextPollAllowedAt = 0L;

		// Applied before the degraded check below, deliberately: a site that is
		// having trouble asks for a slower cadence, and that request is the one
		// thing worth honouring from a degraded response - it's the whole point
		// of the field. Everything else in one is last-known rather than
		// current.
		applyPollCadence(result);

		// The site couldn't reach its own database and answered from a cached
		// copy. Acting on that value could mean deciding an event has ended
		// when it hasn't. Sitting this one out costs at most one poll interval.
		if (result.degraded)
		{
			log.debug("Clan site answered in degraded mode; skipping this tick");
			return;
		}

		boolean wasActive = bingoActive;
		bingoActive = result.bingoActive;

		// An event just started. Team membership is only ever refreshed at
		// startup, on a key change, or right here - never on a recurring timer
		// or in response to the board marker moving (see the removed
		// maybeRefreshMyTeam/MY_TEAM_REFRESH_ON_CHANGE_MILLIS machinery this
		// replaced). At this exact moment every online client is holding
		// whatever it last knew - which for the normal run-up to an event
		// ("build the teams, then flip the switch") is "no team", and the
		// bingo nav icon is hidden on that basis. Re-checking here, once, is
		// what makes flipping the switch reach everyone within about a
		// minute, which is what the 30-minutes-before-start routine assumes.
		// Costs one request per online client, exactly once per event start,
		// not a recurring cost of any kind.
		if (bingoActive && !wasActive)
		{
			refreshMyTeam();
		}

		// The nav icon now tracks whether an event is running, not just team
		// membership. Between events a leftover team assignment (rosters are
		// not cleared by a board reset) otherwise left the board on screen
		// indefinitely for anyone who took part in the previous bingo - and
		// left it there even after an admin removed them from a team, since
		// membership is only re-checked while an event is active.
		if (bingoActive != wasActive)
		{
			updateNavVisibility();
		}

		if (bingoActive)
		{
			// Deliberately NOT re-checked here on any timer or on the board
			// marker moving. That used to re-ask "am I still on my team?" for
			// every online client every time board_changed_at moved for ANY
			// reason - which, on a busy event, means every single drop
			// submission and every admin approval, clan-wide, triggered this
			// per-member, uncacheable, real-database-read endpoint for
			// everyone online, not just whoever's team actually changed. A
			// roster genuinely changing mid-event is rare and already against
			// this clan's own rules ("rosters lock once the event starts");
			// see startUp()/onConfigChanged("apiKey")/the bingo-just-started
			// branch above for the only three moments this is ever asked.
			// Someone added to or moved off a team mid-event needs to restart
			// their client to pick it up - a real, known tradeoff, not an
			// oversight.
			lastPolledVersion = result.boardVersion;
			if (shouldRefreshBoard(result))
			{
				refreshBoard(result.boardVersion);
			}
			// After any board refresh above, so a fetched board isn't
			// immediately overwritten with older numbers.
			applyGoalProgress(result.goalProgress);
			retryPendingSubmissions();
		}
	}

	/**
	 * Whether this tick should pull the board again.
	 *
	 * <p>Two gates, and both matter. Nothing changed since the copy we hold
	 * means there is nothing to fetch at all. And if something did change but
	 * the panel is closed, what changed is display data nobody is looking at,
	 * so it can wait for the slow background refresh that keeps the item-id
	 * watch list current.
	 *
	 * <p>Auto-submission is unaffected either way: it fires off a loot event,
	 * not off a poll, and the watch list it uses only changes when tiles are
	 * edited. Opening the panel gets a fresh board on the next tick.
	 */
	private boolean shouldRefreshBoard(BingoApiClient.PollResponse poll)
	{
		String stamp = poll.boardChangedAt;
		if (poll.boardVersion != null)
		{
			if (poll.boardVersion.equals(lastBoardVersion))
			{
				return false;
			}
			// The site caches the poll until the board changes, so straight
			// after this player's own fresh fetch it can briefly still describe
			// the state from before their submission. An older stamp than the
			// board held is that lag, not a change - following it would put the
			// pre-submission board back.
			if (isOlderStamp(stamp, lastBoardStamp))
			{
				return false;
			}
		}
		else if (lastBoardStamp != null && stamp != null && stamp.equals(lastBoardStamp))
		{
			return false;
		}
		// Somebody is looking at it, so it needs to be right.
		if (isPanelVisible())
		{
			return true;
		}
		// Not on a team and not looking: there is nothing this board could be
		// used for. The only reason to hold one with the panel closed is the
		// item-id watch list that auto-submission checks drops against, and a
		// member who isn't on a team cannot submit anything anyway - the server
		// refuses it. This is the common case by a wide margin: most of the
		// clan runs this plugin for the chat commands and the live-stream
		// notices and is never in a bingo team at all.
		if (myTeamId == null)
		{
			return false;
		}
		return lastBoardStamp == null
			|| System.currentTimeMillis() - lastBoardFetchAt >= BACKGROUND_BOARD_REFRESH_MILLIS;
	}

	/**
	 * Whether change stamp {@code a} is strictly older than {@code b}. Stamps
	 * only ever move forward on the site, so an older one is a lagging cache.
	 * Unknown or unparseable stamps are never "older".
	 */
	static boolean isOlderStamp(String a, String b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		try
		{
			return Instant.parse(a).isBefore(Instant.parse(b));
		}
		catch (DateTimeParseException e)
		{
			return false;
		}
	}

	/**
	 * Whether the bingo sidebar panel is actually on screen.
	 *
	 * <p>RuneLite removes a plugin panel from the sidebar container when a
	 * different one is selected, so Swing's own isShowing() answers this
	 * without depending on a RuneLite API that could move between versions.
	 */
	private boolean isPanelVisible()
	{
		return bingoPanel.isShowing();
	}

	/**
	 * Only ever called from startUp(), onConfigChanged("apiKey"), and the
	 * bingo-just-started branch of onPolled() - never on a recurring timer,
	 * and never in response to the board marker moving. That used to also
	 * happen on any board change, which meant every drop submission and every
	 * admin approval, clan-wide, made every online client re-ask this
	 * per-member, uncacheable endpoint whether its own team had changed -
	 * almost always to learn it hadn't. Team assignment happens before an
	 * event, not during one, and this clan's own rules already say rosters
	 * lock once it starts, so checking once, at the moments membership can
	 * actually change for a given client, is enough. Someone added to or
	 * moved off a team mid-event needs to restart their client to pick it up.
	 */
	private void refreshMyTeam()
	{
		String apiKey = config.apiKey().trim();
		if (apiKey.isEmpty())
		{
			myTeamId = null;
			updateNavVisibility();
			return;
		}
		api.fetchMyTeam(
			apiKey,
			result -> {
				String previous = myTeamId;
				myTeamId = result.teamId;
				updateNavVisibility();
				// Someone just put on a team, or moved to another one, is
				// looking at the wrong half of the board until it is
				// re-rendered - and the change marker cannot help, because the
				// board itself did not change, only which part of it is theirs.
				boolean changed = previous == null
					? result.teamId != null
					: !previous.equals(result.teamId);
				if (changed)
				{
					refreshBoardNow();
					// Joining a team mid-event also changes which cadence
					// applies, and that was decided on the poll this reply came
					// from - before the answer existed. Clearing the last-poll
					// time lets the next scheduled tick re-derive it, rather
					// than leaving a new participant on the non-participant
					// cadence until a whole slow interval has elapsed.
					lastPollAt = 0L;
				}
			},
			error -> log.debug("Failed to fetch team membership: {}", error));
	}

	/**
	 * Shows the bingo nav icon only for members who are actually on a team.
	 * Someone with a plugin key but no team could still open the panel and
	 * see the clan-wide standings, which cost a real board fetch for
	 * information that's already fully public on the website - not worth it
	 * for someone who isn't playing. Called whenever team membership or the
	 * "Show bingo board" toggle change.
	 */
	private void updateNavVisibility()
	{
		if (config.showSidebar() && myTeamId != null && bingoActive)
		{
			clientToolbar.addNavigation(bingoNavButton);
		}
		else
		{
			clientToolbar.removeNavigation(bingoNavButton);
		}
	}

	/**
	 * Adopts the cadence the site asks for - fast while an event is running,
	 * slow otherwise. The server decides rather than the plugin, so it can be
	 * retuned mid-month without waiting for installs to update.
	 */
	private void applyPollCadence(BingoApiClient.PollResponse result)
	{
		if (result.pollSeconds > 0)
		{
			pollIntervalMillis = Math.min(
				POLL_INTERVAL_MAX_MILLIS,
				Math.max(POLL_INTERVAL_MIN_MILLIS, result.pollSeconds * 1000L));
		}
	}

	private void onPollFailed(String error)
	{
		consecutivePollFailures++;
		long delay = Math.min(
			BACKOFF_MAX_MILLIS,
			BACKOFF_BASE_MILLIS * (1L << Math.min(consecutivePollFailures - 1, 8)));
		nextPollAllowedAt = System.currentTimeMillis() + delay;
		log.debug("Clan site poll failed ({}); backing off {}ms", error, delay);
	}

	/**
	 * Fetches the board and rebuilds the item-id lookup that handleLoot()
	 * checks drops against. Team-combined xp/kc tiles need no plugin-side
	 * reporting at all - their progress comes entirely from the website's
	 * own hiscores polling (see osrsclan/api/_lib/board.ts), so this only
	 * ever has to watch for item drops.
	 *
	 * <p>This is the expensive call - it makes the site query tiles, teams,
	 * rosters and every submission, and send back the lot. Almost all of the
	 * time it should be reached through {@link #poll()}, which only calls it
	 * when the board has actually changed. {@link #forceRefreshBoard()} is
	 * for the handful of moments where waiting for that is wrong.
	 *
	 * @param version the poll's boardVersion, or null if unknown. A versioned
	 *                board is cached by the site until the board next changes,
	 *                so a change costs the site one render rather than one per
	 *                plugin; it is also recorded, so later polls can tell
	 *                whether anything has moved since.
	 */
	private void refreshBoard(String version)
	{
		refreshBoard(version, false);
	}

	private void refreshBoard(String version, boolean fresh)
	{
		if (config.apiKey().trim().isEmpty())
		{
			tilesByItemId.clear();
			recentAttempts.clear();
			lastBoardStamp = null;
			lastBoardVersion = null;
			SwingUtilities.invokeLater(bingoPanel::showNoApiKey);
			return;
		}

		api.fetchBoard(
			fresh,
			fresh ? null : version,
			board -> {
				// Never replace the held board with an older one: straight after
				// this player's own fresh fetch, a cached copy can still predate
				// their submission.
				if (isOlderStamp(board.boardChangedAt, lastBoardStamp))
				{
					return;
				}
				// The stamp the board actually came back with, not the one we
				// asked on the strength of: an unversioned cached copy can
				// predate the change that prompted this fetch, and recording a
				// newer stamp for it would leave the panel stuck a change
				// behind. A versioned one cannot - the site renders it from a
				// database already at that version or later.
				lastBoardStamp = board.boardChangedAt;
				lastBoardVersion = fresh ? null : version;
				lastBoardFetchAt = System.currentTimeMillis();
				// Held so a poll can refresh xp/kc numbers on it without
				// re-fetching the whole thing - see applyGoalProgress.
				lastBoard = board;
				// The board is a single cached copy shared by everyone, so it
				// says nothing about who is asking. The team id comes from
				// fetchMyTeam and is stitched in here, so findMyTeam() and the
				// panel keep working exactly as before.
				board.myTeamId = myTeamId;
				SwingUtilities.invokeLater(() -> bingoPanel.refresh(board));

				BoardResponse.Team myTeam = board.findMyTeam();
				List<BoardResponse.Tile> tiles = myTeam == null ? Collections.emptyList() : myTeam.getTiles();

				Map<Integer, List<BoardResponse.Tile>> nextItemLookup = new HashMap<>();
				for (BoardResponse.Tile tile : tiles)
				{
					if (tile.isXpGoal() || tile.isKcGoal())
					{
						continue;
					}
					for (Integer itemId : tile.getItemIds())
					{
						nextItemLookup.computeIfAbsent(itemId, id -> new ArrayList<>()).add(tile);
					}
				}

				tilesByItemId.clear();
				tilesByItemId.putAll(nextItemLookup);
				log.debug("Bingo board refreshed: watching {} item ids", nextItemLookup.size());
			},
			error -> {
				// Leave the version unknown so the next poll tries again
				// rather than concluding the board is already up to date.
				lastBoardVersion = null;
				log.debug("Bingo board refresh failed: {}", error);
			});
	}

	/**
	 * Fetches a board right now, for moments where there isn't one held yet or
	 * it may belong to someone else: plugin startup, an API key change, and
	 * learning which team this key is on. Nothing has *changed* in any of
	 * those, so the shared cached copy is exactly right - these used to ask
	 * for an uncached render, which made every client restart during an event
	 * a full board render from the database.
	 */
	private void refreshBoardNow()
	{
		lastBoardStamp = null;
		lastBoardVersion = null;
		refreshBoard(lastPolledVersion);
	}

	/**
	 * Fetches the board uncached, straight after this player's own submission:
	 * they should see their own drop land immediately, not after the site's
	 * cached copy catches up.
	 */
	private void forceRefreshBoard()
	{
		lastBoardVersion = null;
		refreshBoard(null, true);
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		handleLoot(event.getItems());
	}

	/**
	 * Beams and labels any ground item that still counts toward one of this
	 * player's outstanding tiles - purely visual, makes the specific drop a
	 * proof screenshot needs to show easy to pick out on a cluttered floor,
	 * same reason a tile picker exists for item_requirements submissions.
	 * Doesn't affect detection or auto-submission at all, that's driven by
	 * the loot event in handleLoot(), not by anything ground-item-related.
	 */
	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		if (!config.highlightGroundItems())
		{
			return;
		}
		List<BoardResponse.Tile> candidates = tilesByItemId.get(event.getItem().getId());
		if (candidates == null || candidates.isEmpty())
		{
			return;
		}
		if (!recentlyLootedItemTicks.containsKey(event.getItem().getId()))
		{
			// Not confirmed as a real drop yet - handleLoot() for this exact
			// item may simply not have run yet rather than never running at
			// all (see pendingUnconfirmedSpawns). Hold it briefly instead of
			// assuming a player manually dropped it.
			pendingUnconfirmedSpawns.put(event.getItem(), new PendingSpawn(event, LOOT_GRACE_TICKS));
			return;
		}
		beamItem(event.getItem(), event.getTile().getWorldLocation());
	}

	private void beamItem(TileItem item, WorldPoint location)
	{
		BingoLootbeam beam = new BingoLootbeam(
			client, clientThread, location,
			config.groundItemHighlightColor(), BingoLootbeam.Style.MODERN);
		trackedGroundItems.put(item, new TrackedGroundItem(beam));
	}

	/**
	 * The other half of the onItemSpawned/handleLoot race: a ground item that
	 * spawned before its own loot event reached here waits in
	 * pendingUnconfirmedSpawns rather than going unbeamed forever - this is
	 * what reaches back and beams it the moment confirmation actually arrives.
	 */
	private void confirmPendingSpawns(int itemId)
	{
		if (!config.highlightGroundItems())
		{
			return;
		}
		pendingUnconfirmedSpawns.entrySet().removeIf(entry -> {
			if (entry.getKey().getId() != itemId)
			{
				return false;
			}
			ItemSpawned event = entry.getValue().event;
			beamItem(event.getItem(), event.getTile().getWorldLocation());
			return true;
		});
	}

	/**
	 * Beams anything already sitting on the ground the moment "Highlight
	 * bingo drops" flips back on - the beam system is otherwise purely
	 * reactive to ItemSpawned, a genuinely new spawn event, so a drop that
	 * landed while the toggle was off would otherwise sit there unbeamed
	 * until some entirely separate later drop happened to trigger one.
	 */
	private void rescanGroundItemsForBeams()
	{
		if (tilesByItemId.isEmpty())
		{
			return;
		}
		clientThread.invoke(() -> {
			WorldView worldView = client.getTopLevelWorldView();
			if (worldView == null)
			{
				return;
			}
			Tile[][] planeTiles = worldView.getScene().getTiles()[worldView.getPlane()];
			for (Tile[] column : planeTiles)
			{
				for (Tile tile : column)
				{
					if (tile == null || tile.getGroundItems() == null)
					{
						continue;
					}
					for (TileItem item : tile.getGroundItems())
					{
						if (trackedGroundItems.containsKey(item) || pendingUnconfirmedSpawns.containsKey(item))
						{
							continue;
						}
						List<BoardResponse.Tile> candidates = tilesByItemId.get(item.getId());
						if (candidates != null && !candidates.isEmpty())
						{
							beamItem(item, tile.getWorldLocation());
						}
					}
				}
			}
		});
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		pendingUnconfirmedSpawns.remove(event.getItem());
		TrackedGroundItem tracked = trackedGroundItems.remove(event.getItem());
		if (tracked != null)
		{
			tracked.beam.remove();
		}
	}

	/**
	 * Counts down recentlyLootedItemTicks and pendingUnconfirmedSpawns,
	 * dropping either once its grace window passes. A pending spawn that
	 * expires unconfirmed is left unbeamed for good - its window to be
	 * vouched for by a loot event has passed, same as if it were never
	 * seen at all.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!recentlyLootedItemTicks.isEmpty())
		{
			recentlyLootedItemTicks.replaceAll((itemId, ticks) -> ticks - 1);
			recentlyLootedItemTicks.values().removeIf(ticks -> ticks <= 0);
		}
		if (!pendingUnconfirmedSpawns.isEmpty())
		{
			pendingUnconfirmedSpawns.replaceAll((item, pending) ->
				new PendingSpawn(pending.event, pending.ticksRemaining - 1));
			pendingUnconfirmedSpawns.values().removeIf(pending -> pending.ticksRemaining <= 0);
		}
	}

	/**
	 * Covers loot that doesn't come straight off an NPC corpse - raid chests,
	 * barrows chests, clue caskets and so on.
	 *
	 * <p>Every loot event represents something actually obtained in game. Buying
	 * an item, withdrawing it from the bank or receiving it in a trade does not
	 * produce one, which is what keeps a bought item from being claimed as a
	 * drop.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		handleLoot(event.getItems());
	}

	/** One tile that a single loot event should submit a proof for. */
	private static class PendingCapture
	{
		private final BoardResponse.Tile tile;
		private final int itemId;
		private final String itemName;

		private PendingCapture(BoardResponse.Tile tile, int itemId, String itemName)
		{
			this.tile = tile;
			this.itemId = itemId;
			this.itemName = itemName;
		}
	}

	private void handleLoot(Collection<ItemStack> items)
	{
		if (items == null || tilesByItemId.isEmpty() || config.apiKey().trim().isEmpty())
		{
			return;
		}

		// Every (tile, item) pair this one loot event satisfies is collected
		// first, and the screenshot is taken ONCE for all of them below.
		//
		// It used to request a frame per tile, inside this loop. One item can
		// legitimately belong to several tiles at once (a Bandos hilt counting
		// toward both "any GWD unique" and "2 of 4 hilts", say), and in that
		// case this fired drawManager.requestNextFrameListener twice within the
		// same frame and encoded two identical screenshots of it. Reported from
		// a live event as "the item stops submitting for the other tile" - so
		// whether or not RuneLite delivers every listener registered against
		// one frame, relying on it was never worth it when the frame is
		// identical for all of them anyway. One capture, one encode, N
		// submissions.
		List<PendingCapture> captures = new ArrayList<>();
		for (ItemStack item : items)
		{
			List<BoardResponse.Tile> candidates = tilesByItemId.get(item.getId());
			if (candidates == null)
			{
				continue;
			}
			recentlyLootedItemTicks.put(item.getId(), LOOT_GRACE_TICKS);
			confirmPendingSpawns(item.getId());

			for (BoardResponse.Tile tile : candidates)
			{
				if (!tile.needsMoreProof() || recentlyAttempted(tile.tileId))
				{
					continue;
				}
				// Reading the item name needs the client thread, and we're on it
				// here - resolve it now rather than inside the upload callback.
				captures.add(new PendingCapture(tile, item.getId(), itemName(item.getId())));
			}
		}

		if (captures.isEmpty())
		{
			return;
		}

		// Fired right here, at detection, rather than after the upload
		// succeeds: it's purely cosmetic, so there's no reason to make it wait
		// out a full screenshot-encode + network round trip (which is what
		// made it feel delayed). Once per loot event now rather than once per
		// matching tile, so a drop counting for two tiles no longer dances
		// twice.
		playDropEmote();
		captureAndSubmit(captures);
	}

	private String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (RuntimeException e)
		{
			log.debug("Could not resolve name for item {}", itemId, e);
			return "item " + itemId;
		}
	}

	/**
	 * Delay between a loot event firing and actually requesting a frame -
	 * see the long comment inside captureAndSubmit for why this exists.
	 * Raised from 250ms to a full game tick (2026-09-16): 250ms was already
	 * several render passes of margin for the overlay-composite race that
	 * value was chosen for, but too soon to catch the drop emote looking
	 * like anything more than its wind-up frames - a tick is how long the
	 * game itself takes to advance an animation to a clearly readable pose,
	 * so waiting any less can't reliably show one regardless of render rate.
	 */
	private static final long CAPTURE_DELAY_MILLIS = 600L;

	private void captureAndSubmit(List<PendingCapture> captures)
	{
		// Was: drawManager.requestNextFrameListener(...) called directly from
		// here, i.e. from inside the loot-event handler itself. That asks for
		// literally the very next frame, at the exact instant a game tick is
		// still being processed - there is no guarantee a full render-and-
		// composite pass, overlays included, has actually completed for that
		// frame yet. Confirmed live during the September event: a proof
		// screenshot captured this way was missing the codeword overlay
		// entirely, even though the same overlay was clearly rendering fine
		// moments later in an unrelated, manually-taken screenshot of the
		// same drop - ruling out a config/toggle problem and pointing
		// squarely at a race on which frame gets grabbed.
		//
		// BingoCodewordOverlay's render() has no game-state dependency at
		// all - if the toggle's on, it draws the same thing every single
		// frame - so there's no reason it would be flaky except a timing
		// issue with which frame this code asks for. A short scheduled delay
		// before asking removes the ambiguity: by CAPTURE_DELAY_MILLIS after
		// the event, RuneLite has unquestionably completed at least one full
		// render pass, overlays composited in, so there is no longer a "did
		// this frame include the overlay" race to lose.
		executor.schedule(() -> drawManager.requestNextFrameListener(image -> {
			// Copy the frame before leaving the render callback: the Image the
			// client hands over is not ours to keep.
			BufferedImage frame = ImageUtil.bufferedImageFromImage(image);
			executor.execute(() -> encodeAndUploadAll(captures, frame));
		}), CAPTURE_DELAY_MILLIS, TimeUnit.MILLISECONDS);
	}

	/**
	 * Encodes the shared frame once, then submits it against every tile this
	 * drop counted for. Encoding is the expensive half (a full game frame to
	 * JPEG), and it produced identical bytes per tile before, so doing it once
	 * is both cheaper and the thing that guarantees a multi-tile drop can't
	 * half-submit.
	 */
	private void encodeAndUploadAll(List<PendingCapture> captures, BufferedImage frame)
	{
		byte[] image;
		try
		{
			image = encodeProof(frame);
		}
		catch (IOException e)
		{
			log.warn("Failed to encode bingo screenshot", e);
			for (PendingCapture capture : captures)
			{
				recentAttempts.remove(capture.tile.tileId);
			}
			notifyPlayer("Could not encode the screenshot for " + captures.get(0).itemName);
			return;
		}

		for (PendingCapture capture : captures)
		{
			upload(capture, image);
		}
	}

	/**
	 * Longest edge a proof screenshot is stored at. Only ever shrinks an
	 * oversized frame - most clients are already at or under this, and a
	 * proof nobody can read is worthless, so this is set well above "big
	 * enough to read a chat line" rather than as tight as it could be.
	 */
	private static final int MAX_PROOF_EDGE_PX = 1920;

	/**
	 * JPEG quality for proof screenshots. High enough that the artefacts are
	 * invisible at a glance on a game frame; the point is not to be small, it
	 * is to not be PNG.
	 */
	private static final float PROOF_JPEG_QUALITY = 0.85f;

	/**
	 * Server rejections that mean "there was nothing to do here", as opposed to
	 * something the player can act on.
	 *
	 * <p>The plugin deliberately tries a tile whenever the server hasn't marked
	 * it <em>approved</em> yet, but the server counts <em>pending</em> proofs
	 * toward a tile's requirement too - so any tile sitting at its limit with
	 * unreviewed proofs on it gets attempted on every matching drop and refused
	 * every time. That is correct on both sides and must stay that way (the
	 * plugin can't know how an admin will rule on a pending proof), but it used
	 * to put "not submitted - That tile is already complete" in the player's
	 * chat on every single drop. Reported from a live event as the plugin
	 * having broken, which is exactly the wrong impression: nothing was wrong,
	 * there was simply nothing left to submit.
	 */
	private static boolean isExpectedRejection(String error)
	{
		if (error == null)
		{
			return false;
		}
		String lower = error.toLowerCase(Locale.ROOT);
		return lower.contains("already complete")
			|| lower.contains("already been submitted")
			|| lower.contains("already at required amount");
	}

	/**
	 * Sends one already-encoded proof for one tile.
	 *
	 * <p>Proofs are JPEG rather than lossless PNG: a full game frame is close
	 * to PNG's worst case (it compresses flat colour well and dithered, noisy
	 * 3D output badly), so real proofs were landing around 800KB-1MB each.
	 * That is charged twice over - once against the site's blob storage quota,
	 * which every proof occupies until the board is reset, and again against
	 * its transfer quota every single time somebody opens a tile to look.
	 */
	private void upload(PendingCapture capture, byte[] image)
	{
		BoardResponse.Tile tile = capture.tile;
		api.submitProof(
			config.apiKey().trim(),
			tile.tileId,
			capture.itemId,
			image,
			() -> onSubmitted(capture.itemName, tile.name),
			error -> {
				// A transport failure is worth retrying - both immediately on
				// the next matching drop (the dedupe window, not "forever", is
				// what lets a genuine re-drop after a later admin rejection go
				// through) and via the retry queue in case no further drop
				// ever comes. A rejection from the server is neither.
				if ("Could not reach the clan site".equals(error))
				{
					recentAttempts.remove(tile.tileId);
					PendingSubmissionStore.PendingItem item = pendingStore.saveProof(
						tile.tileId, tile.name, capture.itemId, capture.itemName, image);
					if (item != null)
					{
						enqueueRetry(item);
					}
				}
				if (isExpectedRejection(error))
				{
					log.debug("Bingo proof for {} not needed: {}", tile.name, error);
					return;
				}
				notifyPlayer(capture.itemName + " not submitted - " + error);
			});
	}

	/** Adds an item to the in-memory retry queue, evicting (and deleting from disk) the oldest if it's full. */
	private void enqueueRetry(PendingSubmissionStore.PendingItem item)
	{
		if (retryQueue.size() >= MAX_RETRY_QUEUE)
		{
			PendingSubmissionStore.PendingItem dropped = retryQueue.poll();
			if (dropped != null)
			{
				pendingStore.remove(dropped);
				log.warn("Bingo retry queue full - dropping oldest queued item {}", dropped.id);
			}
		}
		retryQueue.add(item);
	}

	private void retryPendingSubmissions()
	{
		String apiKey = config.apiKey().trim();
		if (apiKey.isEmpty())
		{
			return;
		}

		PendingSubmissionStore.PendingItem item;
		while ((item = retryQueue.poll()) != null)
		{
			retryProofItem(apiKey, item);
		}
	}

	private void retryProofItem(String apiKey, PendingSubmissionStore.PendingItem item)
	{
		byte[] png = pendingStore.readScreenshot(item);
		if (png == null)
		{
			// The screenshot itself is gone (disk issue between sessions) -
			// nothing left to retry with.
			pendingStore.remove(item);
			return;
		}

		api.submitProof(
			apiKey,
			item.tileId,
			item.itemId,
			png,
			() -> {
				pendingStore.remove(item);
				onSubmitted(item.itemName, item.tileName);
			},
			error -> {
				if ("Could not reach the clan site".equals(error))
				{
					enqueueRetry(item);
				}
				else
				{
					pendingStore.remove(item);
					notifyPlayer(item.itemName + " not submitted - " + error);
				}
			});
	}

	/**
	 * Scales the frame down if it is larger than MAX_PROOF_EDGE_PX and encodes
	 * it as JPEG.
	 *
	 * <p>The intermediate is TYPE_INT_RGB rather than whatever the client
	 * handed over: JPEG has no alpha channel, and writing an image that has
	 * one produces either a failure or colour-inverted output depending on the
	 * JDK, rather than anything useful.
	 */
	private static byte[] encodeProof(BufferedImage frame) throws IOException
	{
		int w = frame.getWidth();
		int h = frame.getHeight();
		double scale = Math.min(1.0, (double) MAX_PROOF_EDGE_PX / Math.max(w, h));
		int outW = Math.max(1, (int) Math.round(w * scale));
		int outH = Math.max(1, (int) Math.round(h * scale));

		BufferedImage rgb = new BufferedImage(outW, outH, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = rgb.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(frame, 0, 0, outW, outH, null);
		g.dispose();

		Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpeg");
		if (!writers.hasNext())
		{
			// No JPEG writer on this JVM (shouldn't happen on a standard JDK).
			// A larger PNG is much better than no proof at all.
			ByteArrayOutputStream fallback = new ByteArrayOutputStream();
			ImageIO.write(rgb, "png", fallback);
			return fallback.toByteArray();
		}

		ImageWriter writer = writers.next();
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (ImageOutputStream stream = ImageIO.createImageOutputStream(out))
		{
			writer.setOutput(stream);
			ImageWriteParam params = writer.getDefaultWriteParam();
			if (params.canWriteCompressed())
			{
				params.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
				params.setCompressionQuality(PROOF_JPEG_QUALITY);
			}
			writer.write(null, new IIOImage(rgb, null, null), params);
		}
		finally
		{
			writer.dispose();
		}
		return out.toByteArray();
	}

	/** Common success path for a real proof landing: chat message plus a board refresh. */
	private void onSubmitted(String itemName, String tileName)
	{
		notifyPlayer("Submitted " + itemName + " for tile \"" + tileName + "\"");
		// Straight away, not on the next tick: a player who just got a drop
		// should see it on their own board immediately.
		forceRefreshBoard();
	}

	/**
	 * Plays whichever emote is configured (see {@link DropEmote}) - purely a
	 * local rendering override, not a real triggered emote. {@code
	 * Actor.setAnimation} is the same mechanism the game engine itself uses
	 * to play idle/walk animations on any actor. It's never sent to the
	 * server, so nobody else sees it, and it doesn't block or delay any real
	 * action: the next real animation update (walking, attacking, anything)
	 * simply overwrites it, same as it would overwrite a real emote. Called
	 * from handleLoot() at the moment a matching drop is detected, not from
	 * the upload's success callback - it's cosmetic, so it shouldn't wait out
	 * a screenshot-encode + network round trip.
	 */
	/**
	 * Arbitrary key this plugin owns in the local player's spotanim table (see
	 * Actor#createSpotAnim) - not a real game id, just our own slot so a
	 * second drop emote replaces the first rather than stacking. Deliberately
	 * an unusual value rather than 0/1: the same table is where the game's
	 * own effects (poison, vengeance, and so on) keep theirs, under keys we
	 * have no visibility into, and a small/common key would risk clobbering
	 * one of those instead of just our own previous spotanim.
	 */
	private static final int DROP_EMOTE_SPOTANIM_KEY = 0x42696E67;

	private void playDropEmote()
	{
		DropEmote emote = config.dropEmote();
		if (emote == DropEmote.NONE)
		{
			return;
		}
		clientThread.invokeLater(() -> {
			Player local = client.getLocalPlayer();
			if (local != null)
			{
				local.setAnimation(emote.getAnimationId());
				if (emote.getSpotAnimId() != -1)
				{
					local.createSpotAnim(DROP_EMOTE_SPOTANIM_KEY, emote.getSpotAnimId(), 0, 0);
				}
			}
		});
	}

	private void notifyPlayer(String message)
	{
		if (!config.notifyOnSubmit())
		{
			return;
		}
		sendChatMessage(message, config.submitMessageColor());
	}

	/**
	 * The clan commands (!rank, !verify, !needed, !live, the sync reminder)
	 * always show their result regardless of the "Chat message on submit"
	 * toggle - that setting is specifically about drop-submission
	 * notifications, not a command the player just typed - which is also
	 * why they pass their own clanMessageColor() here rather than sharing
	 * submitMessageColor: a bingo drop notification and a clan command
	 * reply aren't the same kind of message, so one color config shouldn't
	 * govern both.
	 */
	private void sendChatMessage(String message, Color color)
	{
		String colored = ColorUtil.wrapWithColorTag(message, color);
		clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.CONSOLE, "", colored, null));
	}

	/**
	 * Handles "!rank [name]" once it's actually been sent (this is
	 * registerCommandAsync's execute callback, run off the client thread
	 * already). No name defaults to the sender - chatMessage.getName() is
	 * this message's own author for a real sent message, so no client-thread
	 * hop is needed to read it the way client.getLocalPlayer() would require.
	 * A usage mistake only gets a private reply - nothing worth other
	 * viewers seeing - but a real lookup result or failure rewrites the sent
	 * message itself via setChatReply, same as !lvl/!kc. No plugin key
	 * needed: this is a clan-wide feature, not a bingo one.
	 */
	private void onRankCommand(ChatMessage chatMessage, String message)
	{
		String rsn = commandArgument(message, RANK_COMMAND, chatMessage);
		if (rsn.isEmpty())
		{
			sendChatMessage("Usage - " + RANK_COMMAND + " [name]", config.clanMessageColor());
			return;
		}

		api.lookupRank(rsn,
			result -> setChatReply(chatMessage, formatRankResult(result)),
			(error, reason) -> setChatReply(chatMessage, describeRankError(rsn, error, reason)));
	}

	/**
	 * Handles "!verify [name]" - same shape as !rank, but a different,
	 * stricter check: the clan's hard gear/kc gate (see VERIFY_COMMAND's
	 * doc) rather than the rank-tier ladder. Kept as its own command
	 * rather than folded into !rank's reply since they answer genuinely
	 * different questions ("what rank" vs. "do they meet the hard gate").
	 */
	private void onVerifyCommand(ChatMessage chatMessage, String message)
	{
		String rsn = commandArgument(message, VERIFY_COMMAND, chatMessage);
		if (rsn.isEmpty())
		{
			sendChatMessage("Usage - " + VERIFY_COMMAND + " [name]", config.clanMessageColor());
			return;
		}

		api.checkClanRequirement(rsn,
			result -> setChatReply(chatMessage, formatClanRequirementResult(result)),
			(error, reason) -> setChatReply(chatMessage, describeRankError(rsn, error, reason)));
	}

	/**
	 * Handles "!needed [name]" - same shape as !rank (real sent message,
	 * self by default, rewritten in place with the result), just reporting
	 * what's missing for the next rank tier instead of the current one.
	 * Kept as its own command rather than folded into !rank's reply so
	 * that reply can stay a single short line.
	 */
	private void onNeededCommand(ChatMessage chatMessage, String message)
	{
		String rsn = commandArgument(message, NEEDED_COMMAND, chatMessage);
		if (rsn.isEmpty())
		{
			sendChatMessage("Usage - " + NEEDED_COMMAND + " [name]", config.clanMessageColor());
			return;
		}

		api.lookupRank(rsn,
			result -> setChatReply(chatMessage, formatNeededResult(result)),
			(error, reason) -> setChatReply(chatMessage, describeRankError(rsn, error, reason)));
	}

	/**
	 * Handles "!live" the same way as !rank: a real sent message that
	 * setChatReply then overwrites with the result. Needs no plugin key -
	 * live status is public site data, same as the site's own homepage.
	 */
	private void onLiveCommand(ChatMessage chatMessage, String message)
	{
		api.fetchLiveStreams(
			streams -> setChatReply(chatMessage, formatLiveStreams(streams)),
			error -> setChatReply(chatMessage, error));
	}

	/**
	 * Handles "!event [name]". Unlike !rank/!needed, no name defaults to
	 * showing overall standings rather than the sender's own progress -
	 * "!event" alone asking about yourself would be a strange default for a
	 * clan-wide leaderboard command. Needs no plugin key: this is public WOM
	 * competition data, same reasoning as !live.
	 */
	private void onEventCommand(ChatMessage chatMessage, String message)
	{
		String typed = message.length() > EVENT_COMMAND.length()
			? message.substring(EVENT_COMMAND.length()).trim()
			: "";
		String targetName = typed.isEmpty() ? null : Text.sanitize(typed);

		api.fetchEventSummary(
			result -> {
				boolean noRealEvent = "none".equals(result.status) || result.competitions.isEmpty();
				String eventPart = formatEventResult(result, targetName);
				if (!result.bingoActive)
				{
					setChatReply(chatMessage, eventPart);
					return;
				}
				// Shown whenever bingo is active - a real SOTW/BOTW running at
				// the same time must not suppress this, any more than the
				// bingo's own xp/kc tracking competition should (see
				// isRealCompetition server-side). Not `fresh`, and by the last
				// polled version when there is one: the same shared copy every
				// plugin's own board fetch uses, which the site keeps until the
				// board next changes.
				api.fetchBoard(false, lastPolledVersion,
					board -> {
						String standings = formatBingoStandings(board);
						// No real event running means there is nothing for
						// standings to be "in addition to" - the "no
						// BOTW/SOTW" line would just be noise in front of the
						// only thing actually worth saying.
						String combined = noRealEvent ? standings : eventPart + " | " + standings;
						setChatReply(chatMessage, combined);
					},
					error -> setChatReply(chatMessage, eventPart));
			},
			error -> setChatReply(chatMessage, error));
	}

	/** "Bingo: Team A 18/25 (72%) | Team B 14/25 (56%) | Team C 9/25 (36%)" -
	 *  top 3 only, same reasoning and same cap (EVENT_TOP_N) as a
	 *  competition's standings: a long line of team names wraps across
	 *  several chat lines and stops being readable at a glance. */
	private String formatBingoStandings(BoardResponse board)
	{
		List<BoardResponse.Team> teams = new ArrayList<>(board.getTeams());
		if (teams.isEmpty())
		{
			return "Bingo: no teams yet.";
		}
		teams.sort((a, b) -> Integer.compare(b.pct, a.pct));

		StringBuilder text = new StringBuilder("Bingo:");
		int shown = 0;
		for (BoardResponse.Team team : teams)
		{
			if (shown >= EVENT_TOP_N)
			{
				break;
			}
			if (shown > 0)
			{
				text.append(" |");
			}
			text.append(" ").append(team.name).append(" ")
				.append(team.completeCount).append("/").append(team.totalTiles)
				.append(" (").append(team.pct).append("%)");
			shown++;
		}
		return text.toString();
	}

	/** The bit after the command word, or the sender's own name if nothing follows it. */
	private String commandArgument(String message, String command, ChatMessage chatMessage)
	{
		String typed = message.length() > command.length() ? message.substring(command.length()).trim() : "";
		return typed.isEmpty() ? Text.sanitize(chatMessage.getName()) : typed;
	}

	/**
	 * Overwrites the already-sent message's displayed text with the lookup
	 * result - RuneLite's own bundled chat commands (!lvl, !kc, ...) use
	 * this exact mechanism. Purely a local rendering override, same family
	 * as playDropEmote()'s Actor.setAnimation: it changes nothing on the
	 * wire, so it only shows up for other viewers whose own client also has
	 * this command registered.
	 *
	 * <p>Deliberately no explicit color tag here, unlike sendChatMessage()'s
	 * synthesized notifications - this is rewriting a message that was
	 * already sent in whatever channel the player actually typed it into
	 * (clan chat, public chat, a friends chat, ...), so leaving it uncolored
	 * lets it inherit that channel's own color the same way !lvl/!kc's
	 * replies do, including anyone's own "Chat Colors" plugin customization
	 * for that channel. Forcing clanMessageColor() here would override that
	 * per-channel color with one fixed color regardless of where the command
	 * was actually typed.
	 */
	private void setChatReply(ChatMessage chatMessage, String reply)
	{
		clientThread.invokeLater(() -> {
			MessageNode messageNode = chatMessage.getMessageNode();
			messageNode.setRuneLiteFormatMessage(reply);
			client.refreshChat();
		});
	}

	private String describeRankError(String rsn, String error, String reason)
	{
		if ("not-on-runeprofile".equals(reason))
		{
			return rsn + " hasn't synced RuneProfile yet - install it and open your collection log.";
		}
		return "Rank lookup for " + rsn + " failed - " + error;
	}

	private String formatRankResult(BingoApiClient.RankLookupResult result)
	{
		String eligible = result.eligibleRank != null ? result.eligibleRank : "no rank yet";
		return result.rsn + " qualifies for " + eligible + " - " + result.overallSatisfied + "/" + result.overallTotal + " items";
	}

	private String formatClanRequirementResult(BingoApiClient.ClanRequirementResult result)
	{
		return result.meets
			? result.rsn + " meets the clan requirements"
			: result.rsn + " does not meet the clan requirements";
	}

	private String formatNeededResult(BingoApiClient.RankLookupResult result)
	{
		if (result.nextRank == null)
		{
			return result.rsn + " is already at the top rank.";
		}
		if (result.neededForNextRank == null || result.neededForNextRank <= 0)
		{
			return result.rsn + " already qualifies for " + result.nextRank + ".";
		}

		StringBuilder text = new StringBuilder()
			.append(result.rsn).append(" needs ").append(result.neededForNextRank)
			.append(" more for ").append(result.nextRank);
		List<String> missing = result.missingItemNames;
		if (missing != null && !missing.isEmpty())
		{
			text.append(": ");
			int shown = Math.min(5, missing.size());
			text.append(String.join(", ", missing.subList(0, shown)));
			if (missing.size() > shown)
			{
				text.append(", +").append(missing.size() - shown).append(" more");
			}
		}
		return text.toString();
	}

	private String formatLiveStreams(List<BingoApiClient.LiveStream> streams)
	{
		if (streams.isEmpty())
		{
			return "No clan members are live right now.";
		}

		int shown = Math.min(5, streams.size());
		StringBuilder text = new StringBuilder("Live now: ");
		for (int i = 0; i < shown; i++)
		{
			if (i > 0)
			{
				text.append(", ");
			}
			text.append(streams.get(i).displayName);
		}
		if (streams.size() > shown)
		{
			text.append(", +").append(streams.size() - shown).append(" more");
		}
		return text.toString();
	}

	/** Top standings shown per competition before truncating. Keeps a reply
	 *  with several ongoing competitions from flooding chat, and - the more
	 *  common reason this matters - keeps a single competition's line short
	 *  enough to read at a glance: RSNs vary a lot in length, and five of them
	 *  reliably wraps across two or three chat lines as one hard-to-parse
	 *  block of names and numbers. */
	private static final int EVENT_TOP_N = 3;

	private String formatEventResult(BingoApiClient.EventSummaryResponse result, String targetName)
	{
		if ("none".equals(result.status) || result.competitions.isEmpty())
		{
			// Used to branch on result.bingoActive here to say "...but a bingo
			// is!" - now redundant. onEventCommand appends real standings
			// whenever bingo is active, which already says so on its own far
			// more usefully than this placeholder line ever did.
			return "No BOTW/SOTW running right now.";
		}

		boolean upcoming = "upcoming".equals(result.status);
		List<String> parts = new ArrayList<>();
		boolean foundTarget = false;

		for (BingoApiClient.EventCompetition comp : result.competitions)
		{
			String label = "xp".equals(comp.metricType) ? "SOTW" : "BOTW";
			String metric = humanizeMetric(comp.metric);

			if (upcoming)
			{
				parts.add(label + ": " + metric + " starts in " + formatCountdown(comp.startsAt));
				continue;
			}

			if (targetName != null)
			{
				String found = formatPersonalProgress(comp, label, metric, targetName);
				if (found != null)
				{
					parts.add(found);
					foundTarget = true;
				}
				continue;
			}

			parts.add(label + ": " + metric + " (ends in " + formatCountdown(comp.endsAt) + ") - "
				+ formatStandings(comp));
		}

		if (targetName != null && !foundTarget)
		{
			return targetName + " isn't competing in the current event" + (result.competitions.size() > 1 ? "s" : "") + ".";
		}

		return String.join("  |  ", parts);
	}

	/** Null when this player isn't in this specific competition - the caller
	 *  tries the next one before giving up. */
	private String formatPersonalProgress(BingoApiClient.EventCompetition comp, String label, String metric, String targetName)
	{
		List<BingoApiClient.EventParticipation> ranked = rankedParticipants(comp);
		for (int i = 0; i < ranked.size(); i++)
		{
			BingoApiClient.EventParticipation p = ranked.get(i);
			if (p.player != null && targetName.equalsIgnoreCase(p.player.displayName))
			{
				return targetName + ": " + formatNumber(p.progress.gained) + " " + comp.metricType
					+ " gained in " + metric + " " + label + " (rank " + (i + 1) + ")";
			}
		}
		return null;
	}

	private String formatStandings(BingoApiClient.EventCompetition comp)
	{
		List<BingoApiClient.EventParticipation> ranked = rankedParticipants(comp);
		int shown = Math.min(EVENT_TOP_N, ranked.size());
		StringBuilder text = new StringBuilder();
		for (int i = 0; i < shown; i++)
		{
			if (i > 0)
			{
				// A clear separator between entries, not just a space - RuneLite
				// wraps a message this long across two or three chat lines
				// regardless, and without something to mark where one entry ends
				// and the next begins ("1. Name 33  2. Other name 32") the wrap
				// reads as one run-on wall of names and numbers.
				text.append(" | ");
			}
			BingoApiClient.EventParticipation p = ranked.get(i);
			String name = p.player != null ? p.player.displayName : "?";
			// Unit repeated on every entry, deliberately, even though it costs
			// a few extra characters: clan chat scrolls, so the header this
			// entry depends on can easily no longer be visible by the time
			// someone reads this line. Each entry stays meaningful on its own.
			text.append(i + 1).append(". ").append(name).append(" ")
				.append(formatNumber(p.progress.gained)).append(" ").append(comp.metricType);
		}
		return text.toString();
	}

	private List<BingoApiClient.EventParticipation> rankedParticipants(BingoApiClient.EventCompetition comp)
	{
		List<BingoApiClient.EventParticipation> ranked = new ArrayList<>(
			comp.participations == null ? Collections.emptyList() : comp.participations);
		ranked.sort((a, b) -> Long.compare(b.progress.gained, a.progress.gained));
		return ranked;
	}

	private String formatNumber(long value)
	{
		return String.format(Locale.ROOT, "%,d", value);
	}

	/** "kril_tsutsaroth" -> "Kril Tsutsaroth". Good enough for a chat message;
	 *  not attempting proper capitalisation of small words like "of". */
	private String humanizeMetric(String metric)
	{
		if (metric == null || metric.isEmpty())
		{
			return "?";
		}
		String[] words = metric.replace('_', ' ').split(" ");
		StringBuilder text = new StringBuilder();
		for (String word : words)
		{
			if (word.isEmpty())
			{
				continue;
			}
			if (text.length() > 0)
			{
				text.append(' ');
			}
			text.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
		}
		return text.toString();
	}

	/** "3d 4h" / "6h 12m" / "less than a minute" - deliberately coarse, this
	 *  is a rough sense of time left, not a countdown timer. */
	private String formatCountdown(String isoInstant)
	{
		if (isoInstant == null)
		{
			return "an unknown time";
		}
		try
		{
			Instant target = Instant.parse(isoInstant);
			Duration remaining = Duration.between(Instant.now(), target);
			boolean past = remaining.isNegative();
			Duration abs = remaining.abs();

			long days = abs.toDays();
			long hours = abs.toHours() % 24;
			long minutes = abs.toMinutes() % 60;

			String amount;
			if (days > 0)
			{
				amount = days + "d " + hours + "h";
			}
			else if (hours > 0)
			{
				amount = hours + "h " + minutes + "m";
			}
			else if (minutes > 0)
			{
				amount = minutes + "m";
			}
			else
			{
				amount = "under a minute";
			}
			return past ? amount + " ago" : amount;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not parse event timestamp {}", isoInstant, e);
			return "an unknown time";
		}
	}

	/**
	 * Backs the "Remind me to sync RuneProfile" toggle. Only ever detects
	 * "never set up on RuneProfile at all" (a 404 from the site, see
	 * BingoApiClient#lookupRank's reason field) - there's no confirmed way
	 * to tell a stale-but-present sync from a fresh one, so that case isn't
	 * covered. Runs once per session, right after login.
	 */
	private static final String RP_SYNC_CONFIRMED_KEY = "runeProfileSyncConfirmed";
	private static final String RP_SYNC_CHECKED_AT_KEY = "runeProfileSyncCheckedAt";
	private static final long RP_SYNC_RECHECK_MILLIS = 24 * 60 * 60_000L;

	/**
	 * Reminds you once, if you have never set RuneProfile up.
	 *
	 * <p>This fired on every login, for every install, and the endpoint it
	 * calls is the most expensive one on the site - a clan roster lookup plus
	 * three upstream profile fetches - all to answer a question whose answer
	 * almost never changes and, once it is yes, never changes again. With a few
	 * hundred installs that is hundreds of the site's heaviest requests a day
	 * to tell nobody anything.
	 *
	 * <p>So the answer is remembered. Confirmed synced, and it never asks
	 * again. Not synced, and it asks at most once a day rather than once a
	 * session, which is if anything a better reminder - once per session
	 * punishes people who hop worlds or crash.
	 */
	private void checkRuneProfileSync()
	{
		if (!config.remindRuneProfileSync() || checkedRuneProfileSync)
		{
			return;
		}
		if ("true".equals(configManager.getConfiguration(BingoConfig.GROUP, RP_SYNC_CONFIRMED_KEY)))
		{
			checkedRuneProfileSync = true;
			return;
		}
		Long lastCheck = configManager.getConfiguration(
			BingoConfig.GROUP, RP_SYNC_CHECKED_AT_KEY, Long.class);
		if (lastCheck != null && System.currentTimeMillis() - lastCheck < RP_SYNC_RECHECK_MILLIS)
		{
			checkedRuneProfileSync = true;
			return;
		}
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}

		checkedRuneProfileSync = true;
		configManager.setConfiguration(
			BingoConfig.GROUP, RP_SYNC_CHECKED_AT_KEY, System.currentTimeMillis());
		api.lookupRank(local.getName(),
			result -> configManager.setConfiguration(
				BingoConfig.GROUP, RP_SYNC_CONFIRMED_KEY, "true"),
			(error, reason) -> {
				if ("not-on-runeprofile".equals(reason))
				{
					sendChatMessage("You haven't synced RuneProfile yet - install it and open your"
						+ " collection log so rank checks can see your progress.", config.clanMessageColor());
				}
			});
	}

}

package com.timeserved.bingo;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the Time Served clan site.
 *
 * <p>All requests are asynchronous: they're triggered from game event handlers,
 * which run on the client thread, and blocking that would stutter the game.
 *
 * <p>Every URL this plugin ever connects to is either this hardcoded
 * {@code BASE_URL} or, for tile icons, RuneLite's own item sprite cache via
 * {@code ItemManager} (see {@code BingoPanel#loadIconInto}) - never a URL
 * taken from an API response. An earlier version of the tile-icon path had
 * the site send a per-tile {@code iconUrl} that the panel fetched directly
 * with {@code ImageIO.read(new URL(...))}; Plugin Hub review flagged that as
 * exactly the pattern not allowed (a plugin dereferencing a URL supplied by
 * its own API response, rather than one from the user or baked into the
 * jar), so it was replaced with item-id-based icons from {@code ItemManager}
 * instead. Don't reintroduce a server-supplied URL for anything the plugin
 * fetches.
 */
@Slf4j
@Singleton
public class BingoApiClient
{
	private static final String BASE_URL = "https://timeserved.vercel.app";

	/**
	 * The site's API only exposes req.body as raw bytes when the request is
	 * declared as octet-stream, so the real image type travels in a query
	 * param instead (see submitPluginProof in api/board.ts).
	 */
	private static final MediaType OCTET_STREAM = MediaType.parse("application/octet-stream");
	private static final String SCREENSHOT_CONTENT_TYPE = "image/jpeg";
	private static final String LEGACY_SCREENSHOT_CONTENT_TYPE = "image/png";

	/**
	 * Proofs are JPEG now (see BingoPlugin#encodeProof), but the on-disk retry
	 * queue can still hold PNG bytes saved by an earlier version of the plugin
	 * and never successfully sent. Declaring those as JPEG would store a blob
	 * whose content type doesn't match its bytes, which browsers may then
	 * refuse to render - a silently unviewable proof. Sniffing the PNG magic
	 * number costs nothing and keeps those retries correct.
	 */
	private static String contentTypeOf(byte[] image)
	{
		boolean isPng = image.length >= 8
			&& (image[0] & 0xFF) == 0x89
			&& image[1] == 'P' && image[2] == 'N' && image[3] == 'G';
		return isPng ? LEGACY_SCREENSHOT_CONTENT_TYPE : SCREENSHOT_CONTENT_TYPE;
	}

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	public BingoApiClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * Fetches the board: every team's tiles, item ids, progress and
	 * submissions.
	 *
	 * <p>Sent with no key, deliberately. This response is identical for every
	 * member and the site serves one cached copy of it to all of them, which
	 * is what stops a single person's drop costing one full board render per
	 * online member during an event. Adding an Authorization header here would
	 * be asking for a private copy of a public answer.
	 *
	 * <p>It therefore does not say which team is yours - {@link #fetchMyTeam}
	 * answers that separately, and rarely. See BingoPlugin#myTeamId.
	 *
	 * @param fresh   skip every cache - only right after this player's own
	 *                submission
	 * @param version the poll's {@code boardVersion}, or null if unknown. A
	 *                versioned board is cached by the site until the board next
	 *                changes; without one the site falls back to a short window.
	 */
	public void fetchBoard(boolean fresh, String version, Consumer<BoardResponse> onSuccess, Consumer<String> onError)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + "/api/board");
		if (base == null)
		{
			onError.accept("Invalid API base URL");
			return;
		}

		// view=plugin asks for the board with everything BoardResponse does
		// not read already stripped out - per-proof blob and avatar URLs above
		// all, which are most of the payload once an event has real
		// submissions on it and which this plugin was downloading and throwing
		// away on every refresh.
		HttpUrl.Builder builder = base.newBuilder().addQueryParameter("view", "plugin");
		if (fresh)
		{
			// The site caches this response briefly so that one change does not
			// cost one render per online member. That is right for a routine
			// refresh and wrong right after *this* player submitted something:
			// their own drop missing from their own board reads as a bug. A
			// unique query string gets an uncached answer for the handful of
			// refreshes that follow a real action.
			builder.addQueryParameter("fresh", Long.toString(System.currentTimeMillis()));
		}
		else if (version != null && !version.isEmpty())
		{
			builder.addQueryParameter("v", version);
		}
		Request.Builder request = new Request.Builder().url(builder.build()).get();

		httpClient.newCall(request.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to fetch bingo board", e);
				onError.accept("Could not reach the clan site");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						onError.accept(describeFailure(closeable, parseErrorBody(body)));
						return;
					}
					onSuccess.accept(gson.fromJson(body.charStream(), BoardResponse.class));
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed bingo board response", e);
					onError.accept("The clan site returned an unexpected response");
				}
			}
		});
	}

	/** Which team the plugin key's owner is on - mirrors GET /api/board?resource=my-team. */
	public static class MyTeam
	{
		/** Null when the key's owner hasn't been put on a team yet. */
		public String teamId;
	}

	/**
	 * Asks which team this plugin key belongs to.
	 *
	 * <p>The one genuinely per-member thing the board response used to carry,
	 * split out so the board itself can be one cached copy shared by everyone.
	 * Tiny, and asked for rarely - on startup, on a key change, and at most
	 * every half hour after that.
	 */
	public void fetchMyTeam(String apiKey, Consumer<MyTeam> onSuccess, Consumer<String> onError)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + "/api/board");
		if (base == null || apiKey.isEmpty())
		{
			onError.accept("Invalid API base URL");
			return;
		}

		HttpUrl url = base.newBuilder().addQueryParameter("resource", "my-team").build();
		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + apiKey)
			.get()
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to fetch team membership", e);
				onError.accept("Could not reach the clan site");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						onError.accept(describeFailure(closeable, parseErrorBody(body)));
						return;
					}
					MyTeam parsed = gson.fromJson(body.charStream(), MyTeam.class);
					onSuccess.accept(parsed == null ? new MyTeam() : parsed);
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed team membership response", e);
					onError.accept("The clan site returned an unexpected response");
				}
			}
		});
	}

	/**
	 * Everything a bingo participant's once-a-minute tick needs, in one
	 * response.
	 *
	 * <p>This used to also carry clan broadcast and live-stream answers,
	 * merged in from what were three separate requests fired on the same
	 * tick, for every online member regardless of bingo participation -
	 * roughly 4,300 requests per member per day before anyone did anything at
	 * all, and across a clan this size that was the single biggest source of
	 * load on the site by a wide margin, exhausting the hosting plan's quotas.
	 * Broadcast and live-stream notifications were later removed from the
	 * plugin entirely rather than kept merged in, since the only remaining
	 * caller of this endpoint is someone with a plugin key set - i.e. an
	 * actual bingo participant - and neither feature had anything to do with
	 * bingo. See BingoPlugin#hasAnythingToPollFor.
	 *
	 * <p>Deliberately unauthenticated and identical for every caller, so the
	 * site can serve nearly all of these from its CDN without running any
	 * server code or touching its database at all. Don't add a key, a player
	 * name, or anything else per-member to this call - that would give every
	 * member their own cache entry, which is the same as having no cache.
	 */
	public void fetchPluginPoll(Consumer<PollResponse> onSuccess, Consumer<String> onError)
	{
		HttpUrl url = HttpUrl.parse(BASE_URL + "/api/plugin-poll");
		if (url == null)
		{
			onError.accept("Invalid API base URL");
			return;
		}

		Request request = new Request.Builder().url(url).get().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to poll the clan site", e);
				onError.accept("Could not reach the clan site");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						onError.accept(describeFailure(closeable, parseErrorBody(body)));
						return;
					}
					PollResponse parsed = gson.fromJson(body.charStream(), PollResponse.class);
					if (parsed == null)
					{
						onError.accept("The clan site returned an empty response");
						return;
					}
					onSuccess.accept(parsed);
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed poll response", e);
					onError.accept("The clan site returned an unexpected response");
				}
			}
		});
	}

	/** One combined tick's worth of state - mirrors GET /api/plugin-poll. */
	public static class PollResponse
	{
		/** Whether a bingo event is currently running. */
		public boolean bingoActive;

		/**
		 * How many seconds to wait before polling again. The same value for
		 * every member of the clan - see BingoPlugin#applyPollCadence for why
		 * that is deliberate: this carries clan-wide announcements, which must
		 * not arrive sooner for some members than others.
		 *
		 * <p>Set server-side rather than fixed in the plugin so it can be
		 * changed without a release - hosting quotas are monthly and hard, and
		 * plugin installs update whenever they feel like it. 0 or missing
		 * means "use the default". Callers must clamp it - see
		 * BingoPlugin#pollIntervalMillis.
		 */
		public int pollSeconds;

		/**
		 * Opaque marker that changes whenever anything on the board changes.
		 * Compare it against the value the board was last fetched with; only
		 * fetch the board again when it differs. Never parse it - its format
		 * is the server's business and may change.
		 */
		public String boardChangedAt;

		/**
		 * Opaque name for one exact state of the board, xp/kc totals included.
		 * Passed back as the board fetch's {@code v} parameter, which the site
		 * caches until the board next changes - so a change costs the site one
		 * board render, not one per plugin. Null from sites older than
		 * 2026-09-23 and during an outage; fall back to boardChangedAt then.
		 */
		public String boardVersion;

		/**
		 * True when the site answered from a cached copy because its database
		 * was unreachable. The values above are then last-known rather than
		 * current, so callers should sit still rather than act on a change
		 * they can't trust.
		 */
		public boolean degraded;

		/**
		 * Team-combined xp/kc progress, as goal_kind:goal_key -> team id ->
		 * value. Example: {"xp:slayer": {"3": 1250000}}.
		 *
		 * <p>Carried on this tick so an xp/kc number can change without the
		 * board being declared stale. It used to arrive the other way: the
		 * server bumped boardChangedAt whenever progress moved, so every
		 * participant re-downloaded the entire board - every tile, team and
		 * submission - every two minutes for a whole event, to refresh one
		 * number. Progress is per *team*, not per member, so it is identical
		 * for everyone and rides along on the shared cached poll for free.
		 */
		public Map<String, Map<String, Long>> goalProgress;
	}

	/*
	 * fetchBoardState() / BoardState used to live here, wrapping
	 * GET /api/board?resource=status. Both were removed along with their only
	 * caller (BingoPlugin#checkBoardState): that endpoint answers from the same
	 * board_config row as /api/plugin-poll and carries the same bingoActive and
	 * boardChangedAt fields, so asking it on the same tick was a second CDN
	 * cache entry, a second origin invocation and a second database read for an
	 * answer the poll had already delivered.
	 */

	/**
	 * Uploads a screenshot as proof for a tile. The server re-checks that the
	 * item satisfies the tile and that the tile still needs proof, so a stale
	 * local board can't produce a bogus submission.
	 */
	public void submitProof(
		String apiKey,
		String tileId,
		int itemId,
		byte[] screenshot,
		Runnable onSuccess,
		Consumer<String> onError)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + "/api/board");
		if (base == null)
		{
			onError.accept("Invalid API base URL");
			return;
		}

		HttpUrl url = base.newBuilder()
			.addQueryParameter("resource", "plugin-proof")
			.addQueryParameter("tileId", tileId)
			.addQueryParameter("itemId", Integer.toString(itemId))
			.addQueryParameter("contentType", contentTypeOf(screenshot))
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + apiKey)
			.post(RequestBody.create(OCTET_STREAM, screenshot))
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to submit bingo proof", e);
				onError.accept("Could not reach the clan site");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (closeable.isSuccessful())
					{
						onSuccess.run();
						return;
					}
					onError.accept(describeFailure(closeable, parseErrorBody(body)));
				}
			}
		});
	}

	/** Result of a {@link #lookupRank} call - mirrors GET /api/runeprofile-proxy?resource=lookup-rank. */
	public static class RankLookupResult
	{
		public String rsn;

		/** The member's current WOM-group-role-derived rank, or null if unranked. */
		public String currentRank;

		/** The highest rank this account's RuneProfile data actually qualifies for, or null if none. */
		public String eligibleRank;

		public int overallSatisfied;
		public int overallTotal;

		/** The next tier up from eligibleRank, or null if already at the top (or no ranks exist). */
		public String nextRank;

		/** How many more items are needed for nextRank; null when nextRank is null. */
		public Integer neededForNextRank;

		/** Up to 8 item names still missing for nextRank - never null, just possibly empty. */
		public List<String> missingItemNames;
	}

	/**
	 * Runs the exact same rank-progress check as the "Auto-Verify" button on
	 * the clan site's Clan Ranks page, server-side, for the given RSN. Only
	 * ever reports what rank someone qualifies for - there's no way to
	 * actually apply an in-game clan rank from here or anywhere else.
	 *
	 * <p>onError's second argument is the server's machine-readable failure
	 * {@code reason} when it sent one (currently only "not-on-runeprofile"),
	 * or null for anything else (including a plain network failure) - lets
	 * callers like the RuneProfile-sync reminder act on a specific failure
	 * without string-matching the human-readable message.
	 *
	 * <p>No plugin key: this is a read of data that's already fully public
	 * on the clan site with no login needed, so unlike the bingo-specific
	 * calls above, there's nothing here for a key to gate.
	 */
	public void lookupRank(String rsn, Consumer<RankLookupResult> onSuccess, BiConsumer<String, String> onError)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + "/api/runeprofile-proxy");
		if (base == null)
		{
			onError.accept("Invalid API base URL", null);
			return;
		}

		HttpUrl url = base.newBuilder()
			.addQueryParameter("resource", "lookup-rank")
			.addQueryParameter("rsn", rsn)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.get()
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to look up rank for {}", rsn, e);
				onError.accept("Could not reach the clan site", null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						ErrorBody err = parseErrorBody(body);
						onError.accept(describeFailure(closeable, err), err.reason);
						return;
					}
					onSuccess.accept(gson.fromJson(body.charStream(), RankLookupResult.class));
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed rank lookup response", e);
					onError.accept("The clan site returned an unexpected response", null);
				}
			}
		});
	}

	/** Result of a {@link #checkClanRequirement} call - mirrors GET /api/runeprofile-proxy?resource=clan-req. */
	public static class ClanRequirementResult
	{
		public String rsn;

		/** Whether this account satisfies the clan's hard gear/kc requirement. */
		public boolean meets;

		/** Which of the three checks passed (e.g. "Twisted Bow"), or null when meets is false. */
		public String reason;
	}

	/**
	 * Checks the clan's hard gear/kc requirement for the given RSN - the
	 * same three-way check ("6+ Crystal Armour Seeds + an Enhanced Crystal
	 * Weapon Seed", "800+ Corrupted Gauntlet kc", or "a Twisted Bow") the
	 * site itself runs on its Clan Rankings page. Deliberately separate from
	 * {@link #lookupRank}: that reports rank-tier eligibility, this reports
	 * whether a much stricter, single gate is met - two different
	 * questions, so two different commands/endpoints rather than one
	 * overloaded reply.
	 *
	 * <p>No plugin key: same public-data reasoning as lookupRank.
	 */
	public void checkClanRequirement(String rsn, Consumer<ClanRequirementResult> onSuccess, BiConsumer<String, String> onError)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + "/api/runeprofile-proxy");
		if (base == null)
		{
			onError.accept("Invalid API base URL", null);
			return;
		}

		HttpUrl url = base.newBuilder()
			.addQueryParameter("resource", "clan-req")
			.addQueryParameter("rsn", rsn)
			.build();

		Request request = new Request.Builder()
			.url(url)
			.get()
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to check clan requirement for {}", rsn, e);
				onError.accept("Could not reach the clan site", null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						ErrorBody err = parseErrorBody(body);
						onError.accept(describeFailure(closeable, err), err.reason);
						return;
					}
					onSuccess.accept(gson.fromJson(body.charStream(), ClanRequirementResult.class));
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed clan requirement response", e);
					onError.accept("The clan site returned an unexpected response", null);
				}
			}
		});
	}

	/** One currently-live stream - mirrors GET /api/twitch-live's LiveStream shape. */
	public static class LiveStream
	{
		public String username;
		public String displayName;
		public String game;
		public String title;
		public int viewers;
	}

	private static class LiveStreamsResponse
	{
		List<LiveStream> streams;
	}

	/**
	 * Which of the clan's known Twitch channels (site-configured, not
	 * plugin-configured) are live right now. Public data, same as the
	 * site's own homepage widget - no plugin key needed or sent.
	 */
	public void fetchLiveStreams(Consumer<List<LiveStream>> onSuccess, Consumer<String> onError)
	{
		HttpUrl url = HttpUrl.parse(BASE_URL + "/api/twitch-live");
		if (url == null)
		{
			onError.accept("Invalid API base URL");
			return;
		}

		Request request = new Request.Builder().url(url).get().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to fetch live streams", e);
				onError.accept("Could not reach the clan site");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						onError.accept(describeFailure(closeable, parseErrorBody(body)));
						return;
					}
					LiveStreamsResponse parsed = gson.fromJson(body.charStream(), LiveStreamsResponse.class);
					onSuccess.accept(parsed.streams == null ? Collections.emptyList() : parsed.streams);
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed live streams response", e);
					onError.accept("The clan site returned an unexpected response");
				}
			}
		});
	}

	/** One participant's progress in a SOTW/BOTW competition. */
	public static class EventParticipation
	{
		public Player player;

		public static class Player
		{
			public String displayName;
		}

		public Progress progress;

		public static class Progress
		{
			public long gained;
		}
	}

	/** One SOTW/BOTW competition, with every participant's progress. */
	public static class EventCompetition
	{
		public String title;

		/** The WOM metric key, e.g. "slayer" or "vorkath" - display name, not this. */
		public String metric;

		/** "xp" or "kc" - decided server-side from the one skill list the site
		 *  and this plugin both already have to agree on for tile icons,
		 *  rather than this plugin keeping a second copy of it. */
		public String metricType;

		/** ISO instant; only meaningful for an ongoing or upcoming competition. */
		public String startsAt;

		/** ISO instant; only meaningful for an ongoing competition. */
		public String endsAt;

		public List<EventParticipation> participations;
	}

	/** Response shape for GET /api/wom-proxy?type=event-summary. */
	public static class EventSummaryResponse
	{
		/** "ongoing", "upcoming", or "none". */
		public String status;

		/** Every competition matching {@link #status} - almost always one, but
		 *  can be more than one if a BOTW and SOTW happen to overlap, and is
		 *  empty when status is "none". */
		public List<EventCompetition> competitions;

		/**
		 * Only meaningful when {@link #status} is "none" - lets !event tell
		 * "nothing is happening at all" apart from "there's no public
		 * SOTW/BOTW, but a bingo is running". The clan's own bingo-xp-tracking
		 * WOM competitions are filtered out of `competitions` before this
		 * response is built (they aren't real events, nobody is "competing" in
		 * one), so without this field a bingo week would otherwise look
		 * identical to a genuinely quiet one. Absent (defaults false) on every
		 * other status, since it isn't needed there.
		 */
		public boolean bingoActive;
	}

	/**
	 * The RuneLite plugin's `!event` chat command: whichever SOTW/BOTW
	 * competition(s) the clan currently has ongoing (or the next upcoming one,
	 * if none are), with every participant's progress. Public data, same
	 * reasoning as fetchLiveStreams above - no plugin key needed or sent.
	 */
	public void fetchEventSummary(Consumer<EventSummaryResponse> onSuccess, Consumer<String> onError)
	{
		HttpUrl base = HttpUrl.parse(BASE_URL + "/api/wom-proxy");
		if (base == null)
		{
			onError.accept("Invalid API base URL");
			return;
		}
		HttpUrl url = base.newBuilder().addQueryParameter("type", "event-summary").build();
		Request request = new Request.Builder().url(url).get().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Failed to fetch event summary", e);
				onError.accept("Could not reach the clan site");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					ResponseBody body = closeable.body();
					if (!closeable.isSuccessful() || body == null)
					{
						onError.accept(describeFailure(closeable, parseErrorBody(body)));
						return;
					}
					EventSummaryResponse parsed = gson.fromJson(body.charStream(), EventSummaryResponse.class);
					if (parsed == null)
					{
						onError.accept("The clan site returned an empty response");
						return;
					}
					if (parsed.competitions == null)
					{
						parsed.competitions = Collections.emptyList();
					}
					onSuccess.accept(parsed);
				}
				catch (JsonSyntaxException e)
				{
					log.debug("Malformed event summary response", e);
					onError.accept("The clan site returned an unexpected response");
				}
			}
		});
	}

	/** A parsed {"error": "...", "reason": "..."} body - reason is usually absent. */
	private static class ErrorBody
	{
		String error;
		String reason;
	}

	private ErrorBody parseErrorBody(ResponseBody body)
	{
		ErrorBody result = new ErrorBody();
		if (body != null)
		{
			try
			{
				JsonObject json = gson.fromJson(body.charStream(), JsonObject.class);
				if (json != null)
				{
					if (json.has("error"))
					{
						result.error = json.get("error").getAsString();
					}
					if (json.has("reason"))
					{
						result.reason = json.get("reason").getAsString();
					}
				}
			}
			catch (JsonSyntaxException | IllegalStateException e)
			{
				log.debug("Non-JSON error response from clan site", e);
			}
		}
		return result;
	}

	/**
	 * Surfaces the server's own {"error": "..."} message when there is one, so
	 * the player sees "That tile is already complete" rather than "HTTP 409".
	 */
	private String describeFailure(Response response, ErrorBody err)
	{
		if (err.error != null)
		{
			return err.error;
		}

		if (response.code() == 401)
		{
			return "Your plugin key was rejected - generate a new one on the clan site";
		}
		return "The clan site returned an error (" + response.code() + ")";
	}
}

package com.timeserved.bingo;

import com.google.gson.Gson;
import java.io.File;
import java.io.FileOutputStream;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Persists bingo drop proof submissions that failed to send to disk, so a
 * client restart doesn't silently lose them - the previous in-memory-only
 * retry queue was wiped on every restart, which means losing the only
 * evidence of something that actually happened in game, with no way to
 * reconstruct it afterwards.
 */
@Slf4j
@Singleton
public class PendingSubmissionStore
{
	private static final File PENDING_DIR = new File(RuneLite.RUNELITE_DIR, "timeserved-bingo-pending");

	// Garbage-collect anything older than this. Prevents unbounded disk
	// growth if retries keep failing (e.g. the site URL is simply wrong)
	// and nobody notices for a long time.
	private static final long MAX_AGE_MILLIS = TimeUnit.DAYS.toMillis(7);

	private final Gson gson;

	@Inject
	public PendingSubmissionStore(Gson gson)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
	}

	/** One persisted drop proof, awaiting retry. */
	public static class PendingItem
	{
		public String id;
		public long timestamp;

		public String tileId;
		public String tileName;
		public Integer itemId;
		public String itemName;
		public String screenshotFile;
	}

	private void init()
	{
		if (!PENDING_DIR.exists())
		{
			PENDING_DIR.mkdirs();
		}
	}

	/** Persists a failed drop submission (screenshot + tile/item details) to disk. Returns null if the write failed. */
	public PendingItem saveProof(String tileId, String tileName, int itemId, String itemName, byte[] png)
	{
		init();
		PendingItem item = new PendingItem();
		item.timestamp = System.currentTimeMillis();
		item.id = "proof-" + tileId + "-" + item.timestamp;
		item.tileId = tileId;
		item.tileName = tileName;
		item.itemId = itemId;
		item.itemName = itemName;
		item.screenshotFile = item.id + ".png";

		File pngFile = new File(PENDING_DIR, item.screenshotFile);
		try (FileOutputStream fos = new FileOutputStream(pngFile))
		{
			fos.write(png);
		}
		catch (IOException e)
		{
			log.warn("Failed to save pending proof screenshot: {}", e.getMessage());
			return null;
		}

		if (!writeJson(item))
		{
			pngFile.delete();
			return null;
		}
		return item;
	}

	private boolean writeJson(PendingItem item)
	{
		File jsonFile = new File(PENDING_DIR, item.id + ".json");
		try (Writer w = new FileWriter(jsonFile))
		{
			gson.toJson(item, w);
			return true;
		}
		catch (IOException e)
		{
			log.warn("Failed to save pending submission metadata: {}", e.getMessage());
			return false;
		}
	}

	/** Loads everything persisted from a previous session, pruning anything past MAX_AGE_MILLIS as it goes. */
	public List<PendingItem> loadAll()
	{
		init();
		List<PendingItem> result = new ArrayList<>();
		File[] jsonFiles = PENDING_DIR.listFiles((dir, name) -> name.endsWith(".json"));
		if (jsonFiles == null)
		{
			return result;
		}

		long now = System.currentTimeMillis();
		for (File f : jsonFiles)
		{
			try (Reader r = new FileReader(f))
			{
				PendingItem item = gson.fromJson(r, PendingItem.class);
				if (item == null)
				{
					continue;
				}
				if (now - item.timestamp > MAX_AGE_MILLIS)
				{
					log.debug("Pruning expired pending submission {} ({} days old)",
						item.id, TimeUnit.MILLISECONDS.toDays(now - item.timestamp));
					remove(item);
					continue;
				}
				result.add(item);
			}
			catch (Exception e)
			{
				log.warn("Failed to read pending submission {}: {}", f.getName(), e.getMessage());
			}
		}
		return result;
	}

	/** Reads back a proof item's screenshot bytes, or null if missing/unreadable. */
	public byte[] readScreenshot(PendingItem item)
	{
		if (item.screenshotFile == null)
		{
			return null;
		}
		try
		{
			return Files.readAllBytes(new File(PENDING_DIR, item.screenshotFile).toPath());
		}
		catch (IOException e)
		{
			log.warn("Failed to read pending screenshot {}: {}", item.screenshotFile, e.getMessage());
			return null;
		}
	}

	/** Deletes a persisted item (and its screenshot, if it has one) - call once it's been submitted successfully, or given up on. */
	public void remove(PendingItem item)
	{
		if (item.screenshotFile != null)
		{
			new File(PENDING_DIR, item.screenshotFile).delete();
		}
		new File(PENDING_DIR, item.id + ".json").delete();
	}
}

