/*
 * Copied into this plugin's own package from RuneLite's
 * net.runelite.client.plugins.grounditems.Lootbeam (license above applies
 * unchanged) because that class is package-private to the bundled Ground
 * Items plugin and can't be referenced from an external plugin — reflection
 * would work around that, but it's one of the RuneLite Plugin Hub's
 * explicitly disallowed techniques, so a licensed copy is the honest way to
 * get the same real 3D beam effect instead of a flat 2D approximation.
 * Trimmed to just the style this plugin uses; otherwise unchanged.
 */
package com.timeserved.bingo;

import java.awt.Color;
import java.util.function.Function;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.callback.ClientThread;

class BingoLootbeam
{
	private final RuneLiteObject runeLiteObject;
	private final Client client;
	private final ClientThread clientThread;
	private Color color;
	private Style style;

	@RequiredArgsConstructor
	enum Style
	{
		LIGHT(l -> l.client.loadModel(
			5809,
			new short[]{6371},
			new short[]{JagexColor.rgbToHSL(l.color.getRGB(), 1.0d)}
		), anim(AnimationID.ENAKH_LIGHT_STREAMING)),
		MODERN(l ->
		{
			ModelData md = l.client.loadModelData(43330);
			if (md == null)
			{
				return null;
			}

			short hsl = JagexColor.rgbToHSL(l.color.getRGB(), 1.0d);
			int hue = JagexColor.unpackHue(hsl);
			int sat = JagexColor.unpackSaturation(hsl);
			int lum = JagexColor.unpackLuminance(hsl);
			int satDelta = sat > 2 ? 1 : 0;

			return md.cloneColors()
				.recolor((short) 26432, JagexColor.packHSL(hue, sat - satDelta, lum))
				.recolor((short) 26584, JagexColor.packHSL(hue, sat, Math.min(lum + 24, JagexColor.LUMINANCE_MAX)))
				.light(75 + ModelData.DEFAULT_AMBIENT, 1875 + ModelData.DEFAULT_CONTRAST,
					ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
		}, anim(AnimationID.FX_BEAM_IDLE)),
		;

		private final Function<BingoLootbeam, Model> modelSupplier;
		private final Function<BingoLootbeam, Animation> animationSupplier;
	}

	private static Function<BingoLootbeam, Animation> anim(int id)
	{
		return b -> b.client.loadAnimation(id);
	}

	BingoLootbeam(Client client, ClientThread clientThread, WorldPoint worldPoint, Color color, Style style)
	{
		this.client = client;
		this.clientThread = clientThread;
		runeLiteObject = client.createRuneLiteObject();

		this.color = color;
		this.style = style;
		update();
		runeLiteObject.setShouldLoop(true);

		LocalPoint lp = LocalPoint.fromWorld(client, worldPoint);
		runeLiteObject.setLocation(lp, client.getTopLevelWorldView().getPlane());

		runeLiteObject.setActive(true);
	}

	void setColor(Color color)
	{
		if (this.color != null && this.color.equals(color))
		{
			return;
		}

		this.color = color;
		update();
	}

	private void update()
	{
		clientThread.invoke(() ->
		{
			Model model = style.modelSupplier.apply(this);
			if (model == null)
			{
				return false;
			}

			Animation anim = style.animationSupplier.apply(this);

			runeLiteObject.setAnimation(anim);
			runeLiteObject.setModel(model);
			return true;
		});
	}

	void remove()
	{
		runeLiteObject.setActive(false);
	}
}

package com.timeserved.bingo;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Shows the codeword (and, if enabled, a live UTC timestamp) on screen, ported directly from Wise
 * Old Man's own overlay ({@code net.wiseoldman.ui.CodeWordOverlay} in
 * {@code wise-old-man/wiseoldman-runelite-plugin}) rather than reimplemented from screenshots.
 * It's a single RuneLite {@link LineComponent} (codeword on the left, timestamp on the right)
 * inside a resizable {@link OverlayPanel} - no custom paint code. The "sticky to the right",
 * "one line when wide, wraps into extra lines when narrow" behaviour isn't something either
 * plugin builds itself: it's {@link LineComponent}'s own built-in wrapping (once the codeword +
 * timestamp no longer both fit on the panel's current dragged width, it word-wraps the right side
 * into as many extra lines as it needs, right-aligning each one, while the left side keeps its own
 * line(s)), and {@link OverlayPanel} already supplies the resize handles, background panel, and
 * border for free.
 *
 * <p>This is the only codeword overlay - there used to be a second one
 * ({@code BingoVerificationOverlay}) that only rendered for the single frame a proof screenshot
 * captured, so the codeword wouldn't sit on screen the whole session. That's been removed: if this
 * overlay happens to be on when a proof screenshot is captured, {@code drawManager} picks it up
 * like any other on-screen overlay, so a second, capture-only overlay was redundant.
 */
class BingoCodewordOverlay extends OverlayPanel
{
	private static final DateTimeFormatter TIMESTAMP_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm 'UTC'")
		.withZone(ZoneOffset.UTC);

	private final BingoConfig config;

	@Inject
	private BingoCodewordOverlay(BingoConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showLiveCodewordOverlay())
		{
			return null;
		}

		String codeword = config.verificationCode().trim();
		if (codeword.isEmpty())
		{
			return null;
		}

		LineComponent.LineComponentBuilder line = LineComponent.builder()
			.left(codeword)
			.leftColor(config.codewordColor());
		if (config.showCodewordTimestamp())
		{
			line.right(TIMESTAMP_FORMAT.format(Instant.now()))
				.rightColor(config.timestampColor());
		}
		panelComponent.getChildren().add(line.build());

		return super.render(graphics);
	}
}

